ml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:3:\"7.2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:11:\"development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:4;a:5:{s:4:\"data\";s:7:\"release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21907\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:342:\"WordPress 7.2 Beta 4 is ready for download and testing! This beta release is intended for testing and development only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features. Wait, what happened to 7.2 Beta [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:7745:\"\n<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 4 is ready for download and testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This beta release is intended for testing and development</strong> only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Wait, what happened to 7.2 Beta 3???</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/news/2026/10/wordpress-7-1-4/\">WordPress 7.1.4 was released on October 28</a> which included WordPress 7.2 Beta 3.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to Test WordPress 7.2 Beta 4</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can test WordPress 7.2 Beta 4 in any of the following ways:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>WordPress Beta Tester Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noreferrer noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. Select the “Bleeding edge” channel and “Beta/RC Only” stream.</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-beta4.zip\">Beta 4 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line (WP-CLI)</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\" rel=\"noreferrer noopener\" target=\"_blank\">WP-CLI</a> command: <br><code>wp core update --version=7.2-beta4</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use a <a href=\"https://playground.wordpress.net/release\" rel=\"noopener\" target=\"_blank\">7.2 Beta 4 WordPress Playground instance</a> to test the software directly in your browser. No setup required-just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong><strong>December 8, 2026</strong></strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<h2 class=\"wp-block-heading\">What&#8217;s in WordPress 7.2 Beta 4?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">For technical details on the issues addressed since Beta 2, see the following links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=10%2F27%2F2026..11%2F03%2F2026&amp;milestone=7.2&amp;group=component&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\">Closed 7.2 WordPress Core Trac tickets</a> since October 27, 2026</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-10-27&amp;until=2026-11-03\">7.2 Gutenberg commits</a> since October 27, 2026</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Continued Improvements to WordPress 7.2</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 4 continues refining the upcoming release with improvements to accessibility, editor reliability, and developer APIs, alongside additional bug fixes and compatibility updates.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Recent work includes improved keyboard focus visibility in Windows High Contrast mode, refinements to administration interfaces, and fixes for right-to-left block alignment and custom block spacing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Developers will also benefit from continued improvements to the Abilities API, DataViews extensibility, and REST API behavior. Additional fixes strengthen revision handling, input validation, and compatibility across supported environments.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/45910\">Trac #45910</a>, <a href=\"https://core.trac.wordpress.org/ticket/66382\">Trac #66382</a>, <a href=\"https://core.trac.wordpress.org/ticket/66427\">Trac #66427</a>, <a href=\"https://core.trac.wordpress.org/ticket/66383\">Trac #66383</a>, <a href=\"https://core.trac.wordpress.org/ticket/66343\">Trac #66343</a>, <a href=\"https://core.trac.wordpress.org/ticket/66329\">Trac #66329</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Continued Improvements to Ipsum</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The new default theme, Ipsum, continues to receive refinements ahead of WordPress 7.2&#8217;s final release. Recent updates improve accessibility with clearer keyboard focus indicators, more descriptive screen reader links, and better support for right-to-left languages. Additional improvements refine block patterns, touch target spacing, and color palette compatibility with other default themes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66352\">Trac #66352</a>, <a href=\"https://github.com/WordPress/wordpress-develop/pull/15113\">GitHub #15113</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Improved Translation Update Management</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 makes managing translation updates easier by displaying individual available updates on the Updates screen. Administrators can now review and selectively install translation updates, bringing language management in line with the familiar plugin and theme update experience.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/42281\">Trac #42281</a>, <a href=\"https://github.com/WordPress/wordpress-develop/pull/11610\">GitHub #11610</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">How important is your testing?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is a critical part of developing any software, and it’s a meaningful way for anyone to contribute – whether or not you have experience. <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">Details on what to test in WordPress 7.2 are available here</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you encounter an issue, please share it in the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">Alpha/Beta area</a> of the support forums. If you are comfortable submitting a reproducible bug report, you can do so <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. You can also check your issue against this list of <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">known bugs</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general and how to get started? Follow along with the <a href=\"https://make.wordpress.org/test/\">testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Beta 4 haiku</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Where did Beta Three go?<br>A surprise along the way<br>Four arrives on cue</em>.</p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to <a href=\'https://profiles.wordpress.org/audrasjb/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>audrasjb</a>, <a href=\'https://profiles.wordpress.org/courane01/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>courane01</a>, <a href=\'https://profiles.wordpress.org/huzaifaalmesbah/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>huzaifaalmesbah</a> for pre-publish review</em>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"21907\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"WordPress 7.1.4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:51:\"https://wordpress.org/news/2026/10/wordpress-7-1-4/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 28 Oct 2026 17:13:02 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21896\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:388:\"This security release features fixes for multiple issues. Because this is a security release, it is recommended that you update your sites immediately. You can download WordPress 7.1.4 from WordPress.org, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Aaron Jorbin\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:5918:\"\n<p class=\"wp-block-paragraph\">This security release features fixes for multiple issues.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Because this is a security release, it is recommended that you update your sites immediately.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/download/\">download WordPress 7.1.4 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin automatically.<br>WordPress 7.1.4 is a short-cycle release. The next major release will be <a href=\"https://make.wordpress.org/core/7-2/\">version 7.2</a>, currently planned for December 8th.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For more information, please visit the <a href=\"https://wordpress.org/documentation/wordpress-version/version-7-1-4/\">WordPress 7.1.4 HelpHub site</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security updates included in this release</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The security team would like to thank the following people and organizations for responsibly reporting vulnerabilities, and allowing them to be fixed in this release:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>A weakness in the WordPress upgrade process which can lead to remote code execution during the upgrade window, reported by <a href=\"https://www.picussecurity.com/resource/author/umut-bayram\">Umut Bayram</a>.</li>\n\n\n\n<li>A stored XSS with specially crafted block markup, reported by <a href=\"https://www.linkedin.com/in/rafiemuhammad/\">Rafie Muhammad</a> (Awesome Motive, Inc.).</li>\n\n\n\n<li>Privacy Data Removal Requests can be created in a way that leads to stored XSS, reported by Anthropic.</li>\n\n\n\n<li>Multiple stored XSS issues in the Interactivity API independently discovered by AnC and DatNLQ from VietSunshine Cyber Security, rekter0 and Anas cherni, <a href=\"https://decentsecurity.io/\">Marcel Karlsson (whoismarcel)</a>, and Weston Ruter, Jon Surrell, Alex Concha, and Luis Herranz of the WordPress Security Team.</li>\n\n\n\n<li>A stored denial of service issue in the Interactivity API, reported by Jon Surrell of the WordPress Security Team.</li>\n\n\n\n<li>A stored XSS in Customizer selective refresh, reported by <a href=\"https://www.linkedin.com/in/rafiemuhammad/\">Rafie Muhammad</a> (Awesome Motive, Inc.).</li>\n\n\n\n<li>A Stored XSS in the Categories block reported by Ben Bidner of the WordPress Security Team.</li>\n\n\n\n<li>Specially crafted User Logins can lead to a stored XSS reported by Anthropic.</li>\n\n\n\n<li>Unpublished customizer changesets can be discovered by unauthenticated users, reported by <a href=\"https://www.linkedin.com/in/antoniolorensius/\">Antonio Lorensius Silaban</a>.</li>\n\n\n\n<li>A Stored XSS in Playlist and image blocks, reported by Ben Bidner of the WordPress Security Team.</li>\n\n\n\n<li>Stored XSS in <code>core/comments-pagination-next</code> and <code>core/comments-pagination-previous</code> blocks, reported by Alex Concha of the WordPress Security Team.</li>\n\n\n\n<li>Notes can be read by privileged users that lack access to edit the post the note is attached to, reported by Ramon of the WordPress Security Team.</li>\n\n\n\n<li>An update to the bundled root certificates due to the eMudhra revocation.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a> and <a href=\"https://profiles.wordpress.org/ntsekouras/\">Nik Tsekouras</a>. WordPress 7.1.4 would not have been possible without the contributions of the following people:</p>\n\n\n\n<p class=\"is-style-wporg-props-medium wp-block-paragraph\"><a href=\"https://w.org/@jorbin\">Aaron Jorbin</a>, <a href=\"https://w.org/@adamsilverstein\">Adam Silverstein</a>, <a href=\"https://w.org/@xknown\">Alex Concha</a>, <a href=\"https://w.org/@aduth\">Andrew Duthie</a>, <a href=\"https://w.org/@andrewserong\">Andrew Serong</a>, <a href=\"https://w.org/@darerodz\">David Arenas</a>, <a href=\"https://w.org/@dmsnell\">Dennis Snell</a>, <a href=\"https://w.org/@ellatrix\">Ella Van Durpe</a>, <a href=\"https://w.org/@mamaduka\">George Mamadashvili</a>, <a href=\"https://w.org/@isabel_brison\">Isabel Brison</a>, <a href=\"https://w.org/@whyisjake\">Jake Spurlock</a>, <a href=\"https://w.org/@audrasjb\">Jb Audras</a>, <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>, <a href=\"https://w.org/@jonsurrell\">Jon Surrell</a>, <a href=\"https://w.org/@desrosj\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/kirasong/\">Kira Song,</a><a href=\"https://w.org/@lancewillett\">Lance Willett</a>, <a href=\"https://w.org/@luisherranz\">luisherranz</a>, <a href=\"https://w.org/@mciampini\">Marco Ciampini</a>, <a href=\"https://w.org/@marcs0h\">marcs0h</a>, <a href=\"https://w.org/@tyxla\">Marin Atanasov</a>, <a href=\"https://w.org/@santosguillamot\">Mario Santos</a>, <a href=\"https://w.org/@mcsf\">Miguel Fonseca</a>, <a href=\"https://w.org/@ntsekouras\">Nik Tsekouras</a>, <a href=\"https://w.org/@peterwilsoncc\">Peter Wilson</a>, <a href=\"https://w.org/@ramonopoly\">ramonopoly</a>, <a href=\"https://w.org/@rfaile313\">Rudy Faile</a>, <a href=\"https://w.org/@sergeybiryukov\">Sergey Biryukov</a>, <a href=\"https://w.org/@umut3806\">umut3806</a>, <a href=\"https://w.org/@westonruter\">Weston Ruter</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, the security fixes were backported to all branches eligible to receive security fixes (currently through 4.7). As a reminder, <strong>only the most recent version of WordPress is actively supported</strong>. The backports are in progress and will ship as they become ready.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 3 has also been released, containing all applicable fixes.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"21896\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:69:\"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:22:\"WordPress 7.2 Beta 2 \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-2/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 27 Oct 2026 15:49:21 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:5:{i:0;a:5:{s:4:\"data\";s:11:\"Development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:3:\"7.2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:11:\"development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:4;a:5:{s:4:\"data\";s:7:\"release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21890\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:343:\"WordPress 7.2 Beta 2 is ready for download and testing!  This beta release is intended for testing and development only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features. How to Test WordPress 7.2 Beta [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:5990:\"\n<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 2 is ready for download and testing! </p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This beta release is intended for testing and development</strong> only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to Test WordPress 7.2 Beta 2</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can test WordPress 7.2 Beta 2 in any of the following ways:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>WordPress Beta Tester Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noreferrer noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. Select the “Bleeding edge” channel and “Beta/RC Only” stream.</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-beta2.zip\">Beta 2 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line (WP-CLI)</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\" rel=\"noreferrer noopener\" target=\"_blank\">WP-CLI</a> command: <br><code>wp core update --version=7.2-beta2</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use a <a href=\"https://playground.wordpress.net/?site-slug=kind-classic-mountain&amp;networking=no&amp;php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\" rel=\"noopener\" target=\"_blank\">7.2 Beta 2 WordPress Playground instance</a> to test the software directly in your browser. No setup required-just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong><strong>December 8, 2026</strong></strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<h2 class=\"wp-block-heading\">What&#8217;s in WordPress 7.2 Beta 2?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">For technical details on the issues addressed since Beta 1, see the following links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=10%2F21%2F2026..10%2F28%2F2026&amp;milestone=7.2&amp;group=component&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\">Closed 7.2 WordPress Core Trac tickets</a> since October 20, 2026</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-10-21&amp;until=2026-10-28\">7.2 Gutenberg commits</a> since October 20, 2026</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Continued Improvements to WordPress 7.2</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 2 builds on the first beta with additional enhancements, bug fixes, and refinements across the administration experience and developer APIs.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Development continues on the <strong>Abilities API</strong>, including content querying, capability requirements, and improvements to schema handling and permissions. New server-side registration capabilities for <strong>DataViews and DataForm</strong> also provide developers with more ways to extend WordPress interfaces.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Additional work includes improvements to REST API flexibility, admin asset loading, and the transition to modern SVG icons throughout WordPress administration.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66268\">Trac #66268</a>, <a href=\"https://core.trac.wordpress.org/ticket/66325\">Trac #66325</a>, <a href=\"https://core.trac.wordpress.org/ticket/66229\">Trac #66229</a>, <a href=\"https://core.trac.wordpress.org/ticket/66343\">Trac #66343</a>, <a href=\"https://core.trac.wordpress.org/ticket/57548\">Trac #57548</a>, <a href=\"https://core.trac.wordpress.org/ticket/65089\">Trac #65089</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">How important is your testing?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is a critical part of developing any software, and it’s a meaningful way for anyone to contribute – whether or not you have experience. <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">Details on what to test in WordPress 7.2 are available here</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you encounter an issue, please share it in the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">Alpha/Beta area</a> of the support forums. If you are comfortable submitting a reproducible bug report, you can do so <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. You can also check your issue against this list of <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">known bugs</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general and how to get started? Follow along with the <a href=\"https://make.wordpress.org/test/\">testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Beta 2 haiku</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Second beta takes shape<br>New abilities take root<br>WordPress grows stronger</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to <a href=\'https://profiles.wordpress.org/mamaduka/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>mamaduka</a> for pre-publish review</em>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"21890\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"Critical PHP Security Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"https://wordpress.org/news/2026/10/critical-php-security-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 21 Oct 2026 13:44:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21835\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:352:\"The PHP project has announced a security release that fixes two critical security vulnerabilities discovered in PHP. Due to the critical severity of the issues, site owners are encouraged to immediately update their installations of PHP. Your web host may already be working to update PHP and put web application firewall (WAF) rules in place [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"John Blackbourn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2400:\"\n<p class=\"wp-block-paragraph\"><a href=\"https://www.php.net/archive/2026.php#2026-10-21-5\">The PHP project has announced a security release that fixes two critical security vulnerabilities discovered in PHP</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Due to the critical severity of the issues, site owners are encouraged to immediately update their installations of PHP. Your web host may already be working to update PHP and put web application firewall (WAF) rules in place to mitigate the vulnerabilities, but you should still check for updates from your web host and, if necessary, update PHP as soon as possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Within WordPress, you can see which version of PHP your site runs under Tools &gt; Site Health &gt; Info &gt; Server. Many web hosts provide this information in your web hosting administration panel too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">These vulnerabilities are <em>not</em> specific to WordPress and affect any server that hosts a PHP application. No WordPress update is required or planned for these issues.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Versions of PHP prior to 8.2 no longer receive security updates from the PHP project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If your site runs a version prior to this and you manage your own web hosting, you should <em>consider taking your server offline</em> while you prepare to update to a newer version of PHP. This advice is being published by several national cyber security agencies. To quote <a href=\"https://www.ncsc.gov.uk/news/critical-security-issue-affecting-php\">the UK National Cyber Security Centre</a>:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Where immediate remediation is not feasible, organisations should consider taking the system offline until it can be fully mitigated.</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">Further information on wordpress.org:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://wordpress.org/support/update-php/\">Get a faster, more secure website: update PHP today</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/handbook/references/php-compatibility-and-wordpress-versions/\">PHP Compatibility and WordPress Versions</a></li>\n\n\n\n<li><a href=\"https://wordpress.org/documentation/article/faq-my-site-was-hacked/\">FAQ My site was hacked</a></li>\n</ul>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"21835\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:69:\"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:54:\"WordPress 7.2 Beta 1 is Ready for Download and Testing\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-1-is-ready-for-download-and-testing/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 16:02:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:5:{i:0;a:5:{s:4:\"data\";s:11:\"Development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:3:\"7.2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:11:\"development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:4;a:5:{s:4:\"data\";s:7:\"release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21813\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:332:\"This beta release is intended for testing and development only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features. How to Test WordPress 7.2 Beta 1 You can test WordPress 7.2 Beta 1 in any of [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:19827:\"\n<p class=\"wp-block-paragraph\"><strong>This beta release is intended for testing and development</strong> only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to Test WordPress 7.2 Beta 1</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can test WordPress 7.2 Beta 1 in any of the following ways:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>WordPress Beta Tester Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noreferrer noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. Select the “Bleeding edge” channel and “Beta/RC Only” stream.</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-beta1.zip\">Beta 1 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line (WP-CLI)</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\" rel=\"noreferrer noopener\" target=\"_blank\">WP-CLI</a> command: <br><code>wp core update --version=7.2-beta1</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use a <a data-id=\"https://playground.wordpress.net/?php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\" data-type=\"link\" href=\"https://playground.wordpress.net/?php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\" rel=\"noopener\" target=\"_blank\">7.2 Beta 1 WordPress Playground instance</a> to test the software directly in your browser. No setup required-just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong>December 8, 2026</strong>. The full <a data-id=\"https://make.wordpress.org/core/2026/07/03/wordpress-7-1-release-party-schedule/\" data-type=\"link\" href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\" rel=\"noopener\" target=\"_blank\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<h2 class=\"wp-block-heading\">Editing Experience</h2>\n\n\n\n<h3 class=\"wp-block-heading\">Responsive Design Controls</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Building on the responsive design improvements introduced in WordPress 7.1, WordPress 7.2 expands viewport-specific styling to additional design tools and blocks. Creators gain more granular control over how layouts and visual settings adapt across screen sizes, including responsive Gallery settings for columns, image cropping, and aspect ratios.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/80388\">GitHub #80388</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82003\">#82003</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Improved Global Styles and Design Tools</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img data-recalc-dims=\"1\" fetchpriority=\"high\" decoding=\"async\" width=\"1024\" height=\"576\" alt=\"\" class=\"wp-image-21825\" role=\"none\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global-1.webp?resize=1024%2C576&#038;ssl=1\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global-1.webp?resize=1024%2C576&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global-1.webp?resize=300%2C169&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global-1.webp?resize=768%2C432&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global-1.webp?resize=1536%2C864&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global-1.webp?w=1920&amp;ssl=1 1920w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 makes site-wide styling easier to manage with a new <em>Customized</em> filter for finding blocks with modified styles and inherited Global Styles values displayed directly in block inspector controls. Expanded design tools and support for styling form elements provide additional flexibility when creating a consistent visual identity across a site.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/82520\">GitHub #82520</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/76525\">#76525</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/34198\">#34198</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84657\">#84657</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Text Shadow Support</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces new text shadow controls, giving creators more ways to add depth and emphasis to their content. Text shadows can be customized through block settings and defined as presets in <code>theme.json</code>, making it easier to maintain consistent typography across a site.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/pull/73320\">GitHub #73320</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/79584\">GitHub #79584</a>, <a href=\"https://core.trac.wordpress.org/ticket/65869\">Trac #65869</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Easier Navigation Management</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Improvements to the Site Editor make managing navigation links more intuitive. Creators can add, organize, and edit navigation items directly from the editor sidebar, making it easier to maintain site menus without interrupting their editing workflow.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/77069\">GitHub #77069</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Better Collaboration with Notes</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img data-recalc-dims=\"1\" decoding=\"async\" width=\"1024\" height=\"576\" alt=\"\" class=\"wp-image-21820\" role=\"none\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Emojis-in-Notes.webp?resize=1024%2C576&#038;ssl=1\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Emojis-in-Notes.webp?resize=1024%2C576&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/10/Emojis-in-Notes.webp?resize=300%2C169&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/10/Emojis-in-Notes.webp?resize=768%2C432&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/10/Emojis-in-Notes.webp?resize=1536%2C864&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/10/Emojis-in-Notes.webp?w=1920&amp;ssl=1 1920w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces Emoji reactions on notes and a new toolbar icon that makes Notes easier to access and manage. Notes move to the editor canvas, bringing conversations directly into the margin. Users can now keep Notes and the block settings sidebar open simultaneously, making it easier to review feedback while editing content.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A new minimized Notes mode reduces visual clutter, while improvements to positioning and display create a smoother, more consistent collaboration experience.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/79970\">GitHub #79970</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/83786\">GitHub #83786</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/80015\">GitHub #80015</a>, <a href=\"https://core.trac.wordpress.org/ticket/64638\">Trac #64638</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Faster, More Efficient Media Uploads</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 expands client-side media processing to the Media Library, allowing images to be resized, compressed, and converted directly in the browser before being uploaded. This can improve upload performance, reduce server resource usage, and provide better support for modern image formats, particularly on hosting environments with limited image-processing capabilities.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/65661\">Trac #65661</a>, <a href=\"https://github.com/WordPress/wordpress-develop/pull/12585\">GitHub #12585</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">New “On This Day” Dashboard Widget</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces a new <strong>On This Day</strong> dashboard widget that helps users rediscover content published on the same date in previous years. By highlighting posts from the site&#8217;s history, the widget makes it easier to revisit past content, celebrate milestones, and find opportunities to refresh or reshare older posts.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/65116\">Trac #65116</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Block Editor Usability Improvements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 includes a collection of smaller improvements aimed at reducing friction in everyday editing. These changes include clearer error messages, more helpful feedback when something goes wrong, and refinements to common editor interactions, making the editing experience more predictable and approachable.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img data-recalc-dims=\"1\" decoding=\"async\" width=\"1024\" height=\"576\" alt=\"\" class=\"wp-image-21821\" role=\"none\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Error-message-update.webp?resize=1024%2C576&#038;ssl=1\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Error-message-update.webp?resize=1024%2C576&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/10/Error-message-update.webp?resize=300%2C169&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/10/Error-message-update.webp?resize=768%2C432&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/10/Error-message-update.webp?resize=1536%2C864&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/10/Error-message-update.webp?w=1920&amp;ssl=1 1920w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/81453\">GitHub #81453</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82496\">#82496</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84656\">#84656</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84649\">#84649</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">A More Consistent WordPress Admin</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 continues modernizing the administration experience by replacing legacy Dashicons in the admin bar and sidebar with icons from the WordPress icon library. The updated icons bring greater visual consistency between the traditional WordPress dashboard and newer editing interfaces.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/wordpress-develop/pull/12270\">GitHub #12270</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">An Updated Block Settings Experience</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img data-recalc-dims=\"1\" loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" alt=\"\" class=\"wp-image-21822\" role=\"none\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global.webp?resize=1024%2C576&#038;ssl=1\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global.webp?resize=1024%2C576&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global.webp?resize=300%2C169&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global.webp?resize=768%2C432&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global.webp?resize=1536%2C864&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global.webp?w=1920&amp;ssl=1 1920w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">A new DataForm-powered inspector introduces a refreshed approach to managing block settings in the editor. Built on the DataForm component system, this work aims to provide more consistent controls and a more extensible foundation for future block editing improvements.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg\">GitHub Gutenberg</a> · <a href=\"https://make.wordpress.org/core/2026/09/17/call-for-testing-dataform-editor-inspector/\">Call for Testing</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Faster WordPress Administration</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 improves admin performance by modernizing how scripts and stylesheets are loaded. Instead of combining assets into large files, WordPress now loads them individually for better browser caching. A new prefetching mechanism also anticipates which admin screen users are likely to visit next, loading its resources in advance to make navigation between the dashboard, post lists, and editor faster.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/57548\">Trac #57548</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">For Developers</h2>\n\n\n\n<h3 class=\"wp-block-heading\">New Secrets API</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces a <strong>Secrets API</strong>, providing developers with a standardized, secure way to store sensitive credentials such as API keys and authentication tokens. The API supports encryption at rest, credential rotation, and customizable storage providers, helping plugins and integrations manage sensitive information more securely.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://core.trac.wordpress.org/ticket/66187\">Learn more (Trac #66187)</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Random Content Redirects</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 adds support for random content redirects, allowing visitors to discover a randomly selected post through a dedicated URL. This provides a simple way to encourage content exploration and help readers rediscover older posts.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/64498\">Trac #64498</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">More Powerful APIs for Developers</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 expands the <strong>Abilities API</strong> with new capabilities for accessing and querying WordPress data, providing a more consistent foundation for integrations, automation, and AI-powered tools. (<a href=\"https://core.trac.wordpress.org/ticket/66268\">Trac #66268</a>, <a href=\"https://core.trac.wordpress.org/ticket/64605\">#64605</a>, <a href=\"https://core.trac.wordpress.org/ticket/64657\">#64657</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Enhancements to the <strong>Interactivity API</strong> introduce new ways to render trusted HTML and manage reactive navigation, giving developers more flexibility when building dynamic, interactive blocks. (<a href=\"https://core.trac.wordpress.org/ticket/66246\">Trac #66246</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/83092\">Gutenberg PR #83092</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Additional improvements to the <strong>HTML API</strong>, block supports, and responsive design tools provide more reliable markup processing and greater control over how custom blocks are styled and displayed across devices. (<a href=\"https://core.trac.wordpress.org/ticket/65824\">Trac #65824</a>, <a href=\"https://core.trac.wordpress.org/ticket/66150\">#66150</a>, <a href=\"https://core.trac.wordpress.org/ticket/65869\">#65869</a>)</p>\n\n\n\n<h2 class=\"wp-block-heading\">How important is your testing?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is a critical part of developing any software, and it’s a meaningful way for anyone to contribute – whether or not you have experience. <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">Details on what to test in WordPress 7.2 are available here</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you encounter an issue, please share it in the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">Alpha/Beta area</a> of the support forums. If you are comfortable submitting a reproducible bug report, you can do so <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. You can also check your issue against this list of <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">known bugs</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general and how to get started? Follow along with the<a href=\"https://make.wordpress.org/test/\"> testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 will include new features that were previously only available in the Gutenberg plugin. Learn more about Gutenberg updates since WordPress 7.1 in the <a href=\"https://make.wordpress.org/core/tag/gutenberg-new/\">What’s New in Gutenberg</a> posts for versions <a href=\"https://make.wordpress.org/core/2026/08/06/whats-new-in-gutenberg-23-7-05-august/\">23.7</a>, <a href=\"https://make.wordpress.org/core/2026/08/19/whats-new-in-gutenberg-23-8-19-august/\">23.8</a>, <a href=\"https://make.wordpress.org/core/2026/09/02/whats-new-in-gutenberg-23-9-2-september/\">23.9</a>, <a href=\"https://make.wordpress.org/core/2026/09/16/whats-new-in-gutenberg-24-0-16-september/\">24.0</a>, <a href=\"https://make.wordpress.org/core/2026/09/30/whats-new-in-gutenberg-24-1-30-september/\">24.1</a>, <a href=\"https://make.wordpress.org/core/2026/10/14/whats-new-in-gutenberg-24-2-14-october/\">24.2</a>, and 24.3.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What’s new in WordPress 7.2?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">With so much in progress for WordPress 7.2 Beta 1, this is still only the beginning; expect continued refinement with each Beta and RC release ahead of the final release on <strong>December 8, 2026</strong></p>\n\n\n\n<h2 class=\"wp-block-heading\">Just for you: a Beta 1 haiku:</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Ipsum takes the stage<br>Secrets bloom, designs take shape<br>New blocks come alive</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to </em><a href=\'https://profiles.wordpress.org/audrasjb/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>audrasjb</a>, <a href=\'https://profiles.wordpress.org/annezazu/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>annezazu</a>, <a href=\'https://profiles.wordpress.org/adamsilverstein/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>adamsilverstein</a>, <a href=\'https://profiles.wordpress.org/westonruter/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>westonruter</a>, <a href=\'https://profiles.wordpress.org/markoserb/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>markoserb</a>, <a href=\'https://profiles.wordpress.org/im3dabasia1/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>im3dabasia1</a>, <a href=\'https://profiles.wordpress.org/jorbin/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>jorbin</a>, and <a href=\'https://profiles.wordpress.org/noruzzaman/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>noruzzaman</a><em> for proofreading and review.</em></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"21813\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"WordPress 7.1.3 Maintenance and Security Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"https://wordpress.org/news/2026/10/wordpress-7-1-3-maintenance-and-security-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 06 Oct 2026 17:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21753\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:378:\"This security and maintenance release features 7 security fixes and 4 bug fixes. Because this is a security release, it is recommended that you update your sites immediately. You can download WordPress 7.1.3 from WordPress.org, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Jake Spurlock\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:5441:\"\n<p class=\"wp-block-paragraph\">This security and maintenance release features 7 security fixes and <a href=\"https://core.trac.wordpress.org/query?milestone=7.1.3&amp;status=closed&amp;order=priority&amp;col=id&amp;col=summary&amp;col=status&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority\">4 bug fixes</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Because this is a security release, it is recommended that you update your sites immediately.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/wordpress-7.1.3.zip\">download WordPress 7.1.3 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security updates included in this release</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The security team would like to thank the following people and organizations for responsibly reporting vulnerabilities, and allowing them to be fixed in this release:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>A stored XSS on the Comments administration page, exploitable via pending comments, reported by <a href=\"https://trailofbits.com/\">Trail of Bits</a> in collaboration with OpenAI.</li>\n\n\n\n<li>A DoS issue in the <code>WP_Http::make_absolute_url()</code> method, reported by Anthropic</li>\n\n\n\n<li>A second-Order SQL injection in WordPress WXR export, reported by Anthropic</li>\n\n\n\n<li>A weakness allowing Author role users to sticky posts, reported by Anthropic</li>\n\n\n\n<li>Unauthenticated disclosure of comments on private &amp; unpublished posts, reported by <a href=\"https://patchstack.com/\">Ananda Dhakal from Patchstack</a></li>\n\n\n\n<li>Imgur embeds are vulnerable to XSS, reported by <a href=\"https://jackfromeast.github.io/\">Zhengyu Liu</a>, <a href=\"https://jesse-yang.com/\">Jingcheng Yang</a>, and <a href=\"https://gvzhong.github.io/\">Gavin Zhong</a></li>\n\n\n\n<li>Forgeable parameters passed to the <code>{status}_{type}</code> hook can lead to action name collision, reported by Alex Concha of the WordPress security team</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://profiles.wordpress.org/whyisjake/\">Jake Spurlock</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1.3 would not have been possible without the contributions of the following people. Their asynchronous coordination to deliver maintenance and security fixes into a stable release is a testament to the power and capability of the WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://w.org/@jorbin\">Aaron Jorbin</a>, <a href=\"https://w.org/@adamsilverstein\">Adam Silverstein</a>, <a href=\"https://w.org/@adrianmoldovanwp\">Adi Moldovan</a>, <a href=\"https://w.org/@adrianduffell\">Adrian Duffell</a>, <a href=\"https://w.org/@xknown\">Alex Concha</a>, <a href=\"https://w.org/@arkaprabhachowdhury\">Arkaprabha Chowdhury</a>, <a href=\"https://w.org/@iamchitti\">Deepak Kumar</a>, <a href=\"https://w.org/@donniam\">donniam</a>, <a href=\"https://w.org/@ehtis\">Ehtisham Siddiqui</a>, <a href=\"https://w.org/@whyisjake\">Jake Spurlock</a>, <a href=\"https://w.org/@audrasjb\">Jb Audras</a>, <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@joedolson\">Joe Dolson</a>, <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>, <a href=\"https://w.org/@jonsurrell\">Jon Surrell</a>, <a href=\"https://w.org/@desrosj\">Jonathan Desrosiers</a>, <a href=\"https://w.org/@kgagne\">Ken Gagne</a>, <a href=\"https://w.org/@khokansardar\">Khokan Sardar</a>, <a href=\"https://w.org/@lancewillett\">Lance Willett</a>, <a href=\"https://w.org/@lucatume\">lucatume</a>, <a href=\"https://w.org/@marcs0h\">marcs0h</a>, <a href=\"https://w.org/@peterwilsoncc\">Peter Wilson</a>, <a href=\"https://w.org/@paulkevan\">Paul Kevan</a>, <a href=\"https://w.org/@therssoftware\">RS Software</a>, <a href=\"https://w.org/@rfaile313\">Rudy Faile</a>, <a href=\"https://w.org/@sergeybiryukov\">Sergey Biryukov</a>, <a href=\"https://w.org/@siliconforks\">siliconforks</a>, <a href=\"https://w.org/@smerriman\">smerriman</a>, <a href=\"https://w.org/@sabernhardt\">Stephen Bernhardt</a>, <a href=\"https://w.org/@suryakantupadhyay\">Suryakant Upadhyay</a>, <a href=\"https://w.org/@vortfu\">vortfu</a>, <a href=\"https://w.org/@webverts\">webVerts</a>, <a href=\"https://w.org/@westonruter\">Weston Ruter</a>, <a href=\"https://w.org/@yogeshbhutkar\">Yogesh Bhutkar</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, the security fixes are being backported, where necessary, to all branches eligible to receive security fixes (currently through 4.7). As a reminder, <strong>only the most recent version of WordPress is actively supported</strong>. The backports are in progress and will ship as they become ready.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to contribute</h2>\n\n\n\n<p class=\"wp-block-paragraph\">To get involved in WordPress core development, head over to Trac, <a href=\"https://core.trac.wordpress.org/report/6\">pick a ticket</a>, and join the conversation in the <a href=\"https://wordpress.slack.com/archives/C02RQBWTW\">#core</a> channel. Need help? Check out the <a href=\"https://make.wordpress.org/core/handbook/\">Core Contributor Handbook</a>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"21753\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"WordPress 7.1.2 Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://wordpress.org/news/2026/09/wordpress-7-1-2-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 22 Sep 2026 14:01:20 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21731\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:391:\"This security release features a fix for a critical severity security vulnerability. Because this is a security release, it is recommended that you update your sites immediately. You can download WordPress 7.1.2 from WordPress.org, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"John Blackbourn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:3427:\"\n<p class=\"wp-block-paragraph\">This security release features a fix for a critical severity security vulnerability.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Because this is a security release, it is recommended that you update your sites immediately.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/download/\">download WordPress 7.1.2 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security update included in this release</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The security team would like to thank <a href=\"https://ressl.ch/\">Robert Ressl</a> for responsibly disclosing that an unauthenticated attacker can, under certain conditions, make page template resolution include a chosen readable local PHP file outside the active theme directories. If relevant pre-conditions for both the server environment and the active theme are met, this can lead to remote code execution (RCE).</p>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>. WordPress 7.1.2 would not have been possible without the contributions of the following people:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://w.org/@jorbin\">Aaron Jorbin</a>, <a href=\"https://w.org/@wildworks\">Aki Hamano</a>, <a href=\"https://w.org/@xknown\">Alex Concha</a>, <a href=\"https://w.org/@ehti\">Ehtisham Siddiqui</a>, <a href=\"https://w.org/@fiocavallari\">fiocavallari</a>, <a href=\"https://w.org/@audrasjb\">Jb Audras</a>, <a href=\"https://w.org/@jeffpaul\">Jeffrey Paul</a>, <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@joemcgill\">Joe McGill</a>, <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>, <a href=\"https://w.org/@jonsurrell\">Jon Surrell</a>, <a href=\"https://w.org/@lancewillett\">Lance Willett</a>, <a href=\"https://w.org/@sirlouen\">Manuel Camargo</a>, <a href=\"https://w.org/@marcs0h\">marcs0h</a>, <a href=\"https://w.org/@martinkrcho\">martin.krcho</a>, <a href=\"https://w.org/@mukesh27\">Mukesh Panchal</a>, <a href=\"https://w.org/@oglekler\">Olga Gleckler</a>, <a href=\"https://w.org/@swissspidy\">Pascal Birchler</a>, <a href=\"https://w.org/@peterwilsoncc\">Peter Wilson</a>, <a href=\"https://w.org/@rajinsharwar\">Rajin Sharwar</a>, <a href=\"https://w.org/@ressl\">Ressl</a>, <a href=\"https://w.org/@rfaile313\">Rudy Faile</a>, <a href=\"https://w.org/@sergeybiryukov\">Sergey Biryukov</a>, <a href=\"https://w.org/@shailu25\">Shail Mehta</a>, <a href=\"https://w.org/@pypwalters\">Stephanie Walters</a>, and <a href=\"https://w.org/@vortfu\">vortfu</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">CVE and GHSA references</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Further details can be found in the advisory: <a href=\"https://github.com/WordPress/wordpress-develop/security/advisories/GHSA-7hp8-65ch-5whp\">CVE-2026-87902 / GHSA-7hp8-65ch-5whp</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, the security fix was backported to all branches eligible to receive security fixes (currently through 4.7). As a reminder, <strong>only the most recent version of WordPress is actively supported</strong>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"21731\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:63:\"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"WordPress Takes Its Turn Leading the Open Website Alliance\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:49:\"https://wordpress.org/news/2026/09/owa-president/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 21 Sep 2026 14:28:41 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:3:{i:0;a:5:{s:4:\"data\";s:7:\"General\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:21:\"Open Website Alliance\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:3:\"owa\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21709\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:379:\"I’m happy to announce that I am now serving as president of the Open Website Alliance (OWA), representing the WordPress Foundation. The Alliance brings together the community organizations behind Drupal, Joomla!, TYPO3, and WordPress to advocate for open source and share practices that benefit their projects. I represent the WordPress Foundation in this role, which [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Mary Hubbard\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2977:\"\n<p class=\"wp-block-paragraph\">I’m happy to announce that I am now serving as president of the <a href=\"https://openwebsitealliance.org/\">Open Website Alliance</a> (OWA), representing the WordPress Foundation. The Alliance brings together the community organizations behind <a href=\"https://www.drupal.org/\">Drupal</a>, <a href=\"https://www.joomla.org/\">Joomla!</a>, <a href=\"https://typo3.org/\">TYPO3</a>, and WordPress to advocate for open source and share practices that benefit their projects. I represent the WordPress Foundation in this role, which rotates among the Alliance’s members.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img data-recalc-dims=\"1\" loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/09/image-3.png?resize=1024%2C576&#038;ssl=1\" alt=\"\" class=\"wp-image-21712\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/09/image-3.png?resize=1024%2C576&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/09/image-3.png?resize=300%2C169&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/09/image-3.png?resize=768%2C432&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/09/image-3.png?resize=1536%2C864&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/09/image-3.png?w=1600&amp;ssl=1 1600w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress <a href=\"https://x.com/WordPress/status/1755516866485707064\">announced its participation in the Alliance in 2024</a>, building on our work with Drupal, Joomla!, and TYPO3 to <a href=\"https://wordpress.org/news/2023/08/concerns-over-the-european-unions-cyber-resilience-act-cra/\">respond to the European Union’s Cyber Resilience Act</a>. While many open source projects focus on underlying digital infrastructure, our content management systems power the websites where businesses reach customers and sell products and services. We asked policymakers to account for that economic role when setting security requirements, while respecting how communities of developers, translators, educators, and other contributors build and maintain the software. We share a belief that everyone should have the freedom to use, change, and share the tools they rely on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This commitment to openness builds on efforts such WordPress’s recent signing of the <a href=\"https://wordpress.org/news/2026/08/open-weight/\">Open Weights and American AI Leadership letter</a>. Our mission to democratize publishing means giving anyone a voice and welcoming everyone to contribute. Working with other communities puts those values into practice beyond WordPress, supporting the freedoms that make participation possible. I invite you to read the <a href=\"https://openwebsitealliance.org/charter.html\">Open Website Alliance charter</a> to learn more about the commitments its members share and how the Alliance works.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"21709\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"WordPress 7.1.1 Maintenance and Security Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"https://wordpress.org/news/2026/09/wordpress-7-1-1-maintenance-and-security-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 17 Sep 2026 19:53:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21717\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:364:\"This security and maintenance release features 17 bug fixes on Core, 19 bug fixes for the Block Editor, and 11 security fixes. Because this is a security release, it is recommended that you update your sites immediately. You can download WordPress 7.1.1 from WordPress.org, or visit your WordPress Dashboard, click “Updates”, and then click “Update [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Aaron Jorbin\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:12839:\"\n<p class=\"wp-block-paragraph\">This security and maintenance release features <a href=\"https://core.trac.wordpress.org/query?milestone=7.1.1&amp;status=closed&amp;group=status&amp;order=priority\">17 bug fixes on Core</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82383\">19 bug fixes for the Block Editor</a>, and 11 security fixes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Because this is a security release, it is recommended that you update your sites immediately.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/wordpress-7.1.1.zip\">download WordPress 7.1.1 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1.1 is a short-cycle release. The next major release will be <a href=\"https://make.wordpress.org/core/7-2/\">version 7.2</a> and is currently planned for December.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For more information, please visit the&nbsp;<a href=\"https://wordpress.org/documentation/wordpress-version/version-7-1-1/\" data-type=\"link\" data-id=\"https://wordpress.org/documentation/wordpress-version/version-7-1-1/\">WordPress 7.1.1 HelpHub site</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security updates included in this release</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The security team would like to thank the following people for responsibly reporting vulnerabilities, and allowing them to be fixed in this release:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Stored cross-site scripting in <code>wpautop()</code> allows an unauthenticated visitor to inject script (subject to comment approval), reported by <a href=\"https://www.linkedin.com/in/rafiemuhammad/\">Rafie Muhammad</a> (Awesome Motive, Inc.).</li>\n\n\n\n<li>HTML API: <code>set_modifiable_text()</code> allows breaking out of a comment via abrupt-closing sequences, reported by <a href=\"https://happyprime.co/\">Jeremy Felt</a> of the WordPress Security Team.</li>\n\n\n\n<li>Stored XSS in some themes that support custom headers, reported by <a href=\"https://happyprime.co/\">Jeremy Felt</a> of the WordPress Security Team.</li>\n\n\n\n<li>Specially crafted URLs can automatically install and preview an inactive theme from WordPress.org, reported by Paulos Yibelo and <a href=\"https://pwn.ai/\">pwn.ai</a>.</li>\n\n\n\n<li>Site Administrator can network-activate an installed Network-only plugin, reported by <a href=\"https://profiles.wordpress.org/buffer1024/\">Jesse McNeil</a>.</li>\n\n\n\n<li>Authenticated Path Traversal in WP REST Templates Controller, reported by Anthropic.</li>\n\n\n\n<li>XML-RPC can be used to publish <code>customize_changeset</code> posts that bypass checks for <code>edit_css</code>, reported by Ben Bidner of the WordPress Security Team.</li>\n\n\n\n<li>Contributor+ Arbitrary Post Overwrite, reported by Anthropic.</li>\n\n\n\n<li>Missing <code>read_post</code> check in <code>attachment_submitbox_metadata()</code> leaks a private parent-post title, reported by <a href=\"https://hdwsec.fr/\">HDWSec</a>.</li>\n\n\n\n<li>Missing Authorization leads to Draft/Pending Post Slug Disclosure by Contributor+, reported by Jakub Herman.</li>\n\n\n\n<li>Comments, including notes, can be reparented by any authenticated user, reported by Justin Hart, Viridis Security.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://profiles.wordpress.org/adamsilverstein/\">Adam Silverstein</a>, <a href=\"https://profiles.wordpress.org/adrianduffell/\">Adrian Duffell</a>, <a href=\"https://profiles.wordpress.org/andraganescu/\">Andrei Draganescu</a>, and <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1.1 would not have been possible without the contributions of the following people. Their asynchronous coordination to deliver maintenance and security fixes into a stable release is a testament to the power and capability of the WordPress community.</p>\n\n\n\n<p class=\"is-style-wporg-props-long wp-block-paragraph\"><a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a>, <a href=\"https://profiles.wordpress.org/abrahamfariaz/\">abrahamfariaz</a>, <a href=\"https://profiles.wordpress.org/adamsilverstein/\">Adam Silverstein</a>, <a href=\"https://profiles.wordpress.org/adrianmoldovanwp/\">Adi Moldovan</a>, <a href=\"https://profiles.wordpress.org/adrianduffell/\">Adrian Duffell</a>, <a href=\"https://profiles.wordpress.org/wildworks/\">Aki Hamano</a>, <a href=\"https://profiles.wordpress.org/xknown/\">Alex Concha</a>, <a href=\"https://profiles.wordpress.org/afercia/\">Andrea Fercia</a>, <a href=\"https://profiles.wordpress.org/andreasca/\">andreasca</a>, <a href=\"https://profiles.wordpress.org/andraganescu/\">Andrei Draganescu</a>, <a href=\"https://profiles.wordpress.org/aduth/\">Andrew Duthie</a>, <a href=\"https://profiles.wordpress.org/andrewserong/\">Andrew Serong</a>, <a href=\"https://profiles.wordpress.org/oandregal/\">André Maneiro</a>, <a href=\"https://profiles.wordpress.org/annezazu/\">annezazu</a>, <a href=\"https://profiles.wordpress.org/antwonw/\">Anthony White</a>, <a href=\"https://profiles.wordpress.org/arkaprabhachowdhury/\">Arkaprabha Chowdhury</a>, <a href=\"https://profiles.wordpress.org/fushar/\">Ashar Fuadi</a>, <a href=\"https://profiles.wordpress.org/azragh/\">Azragh</a>, <a href=\"https://profiles.wordpress.org/barry/\">Barry</a>, <a href=\"https://profiles.wordpress.org/buffer1024/\">buffer1024</a>, <a href=\"https://profiles.wordpress.org/jack960330/\">Chunhui Ouyang</a>, <a href=\"https://profiles.wordpress.org/courane01/\">Courtney Robertson</a>, <a href=\"https://profiles.wordpress.org/dugi-digitaly/\">Dagan</a>, <a href=\"https://profiles.wordpress.org/talldanwp/\">Daniel Richards</a>, <a href=\"https://profiles.wordpress.org/villanovachile/\">Daniel Rodriguez</a>, <a href=\"https://profiles.wordpress.org/darshitrajyaguru97/\">Darshit Rajyaguru</a>, <a href=\"https://profiles.wordpress.org/davidbinda/\">David Biňovec</a>, <a href=\"https://profiles.wordpress.org/iamchitti/\">Deepak Kumar</a>, <a href=\"https://profiles.wordpress.org/dmsnell/\">Dennis Snell</a>, <a href=\"https://profiles.wordpress.org/saiful09/\">DevSaiful</a>, <a href=\"https://profiles.wordpress.org/dhruvang21/\">Dhruvang21</a>, <a href=\"https://profiles.wordpress.org/ocean90/\">Dominik Schilling</a>, <a href=\"https://profiles.wordpress.org/ehtis/\">Ehtisham Siddiqui</a>, <a href=\"https://profiles.wordpress.org/ellatrix/\">Ella Van Durpe</a>, <a href=\"https://profiles.wordpress.org/r1k0/\">Erick Wambua</a>, <a href=\"https://profiles.wordpress.org/fahimmurshed/\">FahimMurshed</a>, <a href=\"https://profiles.wordpress.org/fernandot/\">Fernando Tellado</a>, <a href=\"https://profiles.wordpress.org/fiocavallari/\">fiocavallari</a>, <a href=\"https://profiles.wordpress.org/mamaduka/\">George Mamadashvili</a>, <a href=\"https://profiles.wordpress.org/poseidonas/\">George Vasiliades</a>, <a href=\"https://profiles.wordpress.org/gregbenz/\">gregbenz</a>, <a href=\"https://profiles.wordpress.org/harishtewari/\">Harish Tewari</a>, <a href=\"https://profiles.wordpress.org/hbhalodia/\">Hit Bhalodia</a>, <a href=\"https://profiles.wordpress.org/isabel_brison/\">Isabel Brison</a>, <a href=\"https://profiles.wordpress.org/whyisjake/\">Jake Spurlock</a>, <a href=\"https://profiles.wordpress.org/jdab/\">Jamie Dąbrowiecki</a>, <a href=\"https://profiles.wordpress.org/audrasjb/\">Jb Audras</a>, <a href=\"https://profiles.wordpress.org/jeffpaul/\">Jeffrey Paul</a>, <a href=\"https://profiles.wordpress.org/jeremyfelt/\">Jeremy Felt</a>, <a href=\"https://profiles.wordpress.org/kimjiwoon/\">Jiwoon Kim</a>, <a href=\"https://profiles.wordpress.org/joedolson/\">Joe Dolson</a>, <a href=\"https://profiles.wordpress.org/joehoyle/\">Joe Hoyle</a>, <a href=\"https://profiles.wordpress.org/joemcgill/\">Joe McGill</a>, <a href=\"https://profiles.wordpress.org/joen/\">Joen Asmussen</a>, <a href=\"https://profiles.wordpress.org/timse201/\">Johannes Jülg</a>, <a href=\"https://profiles.wordpress.org/johnbillion/\">John Blackbourn</a>, <a href=\"https://profiles.wordpress.org/jonsurrell/\">Jon Surrell</a>, <a href=\"https://profiles.wordpress.org/desrosj/\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/jmccallweb/\">Josh</a>, <a href=\"https://profiles.wordpress.org/ekamran/\">Kamran Abdul Aziz</a>, <a href=\"https://profiles.wordpress.org/khokansardar/\">Khokan Sardar</a>, <a href=\"https://profiles.wordpress.org/kirasong/\">Kira Schroder</a>, <a href=\"https://profiles.wordpress.org/kleisauke/\">kleisauke</a>, <a href=\"https://profiles.wordpress.org/kush123/\">Kushagra Goyal</a>, <a href=\"https://profiles.wordpress.org/l1onofjudah/\">l1onofjudah</a>, <a href=\"https://profiles.wordpress.org/lancewillett/\">Lance Willett</a>, <a href=\"https://profiles.wordpress.org/luksusspokoju/\">luksusspokoju</a>, <a href=\"https://profiles.wordpress.org/manzoorwanijk/\">Manzoor Wani</a>, <a href=\"https://profiles.wordpress.org/mciampini/\">Marco Ciampini</a>, <a href=\"https://profiles.wordpress.org/marcs0h/\">marcs0h</a>, <a href=\"https://profiles.wordpress.org/tyxla/\">Marin Atanasov</a>, <a href=\"https://profiles.wordpress.org/mgyura/\">Michael</a>, <a href=\"https://profiles.wordpress.org/batmoo/\">Mohammad Jangda</a>, <a href=\"https://profiles.wordpress.org/mrkenobi/\">mrkenobi</a>, <a href=\"https://profiles.wordpress.org/mukesh27/\">Mukesh Panchal</a>, <a href=\"https://profiles.wordpress.org/nkpathan/\">Nawazkhan Pathan</a>, <a href=\"https://profiles.wordpress.org/ntsekouras/\">Nik Tsekouras</a>, <a href=\"https://profiles.wordpress.org/parthjoginyusoft/\">Parth Jogi</a>, <a href=\"https://profiles.wordpress.org/swissspidy/\">Pascal Birchler</a>, <a href=\"https://profiles.wordpress.org/pbiron/\">Paul Biron</a>, <a href=\"https://profiles.wordpress.org/paulkevan/\">Paul Kevan</a>, <a href=\"https://profiles.wordpress.org/peterwilsoncc/\">Peter Wilson</a>, <a href=\"https://profiles.wordpress.org/rafiem/\">Rafie Muhammad</a>, <a href=\"https://profiles.wordpress.org/ramonopoly/\">ramonopoly</a>, <a href=\"https://profiles.wordpress.org/wprashed/\">Rashed Hossain</a>, <a href=\"https://profiles.wordpress.org/ressl/\">Ressl</a>, <a href=\"https://profiles.wordpress.org/youknowriad/\">Riad Benguella</a>, <a href=\"https://profiles.wordpress.org/rfaile313/\">Rudy Faile</a>, <a href=\"https://profiles.wordpress.org/sainathpoojary/\">Sainath Poojary</a>, <a href=\"https://profiles.wordpress.org/sc0ttkclark/\">Scott Kingsley Clark</a>, <a href=\"https://profiles.wordpress.org/sergeybiryukov/\">Sergey Biryukov</a>, <a href=\"https://profiles.wordpress.org/shailu25/\">Shail Mehta</a>, <a href=\"https://profiles.wordpress.org/shameemreza/\">Shameem – a11n</a>, <a href=\"https://profiles.wordpress.org/siliconforks/\">siliconforks</a>, <a href=\"https://profiles.wordpress.org/slaffik/\">Slava Abakumov</a>, <a href=\"https://profiles.wordpress.org/sabernhardt/\">Stephen Bernhardt</a>, <a href=\"https://profiles.wordpress.org/sukhendu2002/\">Sukhendu Sekhar Guria</a>, <a href=\"https://profiles.wordpress.org/ugyensupport/\">Ugyen Dorji</a>, <a href=\"https://profiles.wordpress.org/utsavladani/\">Utsav Ladani</a>, <a href=\"https://profiles.wordpress.org/vortfu/\">vortfu</a>, <a href=\"https://profiles.wordpress.org/westonruter/\">Weston Ruter</a>, <a href=\"https://profiles.wordpress.org/w3bdsgn/\">w3bdsgn</a>, <a href=\"https://profiles.wordpress.org/wolf45/\">wolf45</a> plus representatives from Automattic, Bluehost, GoDaddy, Pantheon, and WP Engine.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, the security fixes are being backported, where necessary, to all branches eligible to receive security fixes (currently through 4.7). As a reminder, <strong>only the most recent version of WordPress is actively supported</strong>. The backports are in progress and will ship as they become ready.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to contribute</h2>\n\n\n\n<p class=\"wp-block-paragraph\">To get involved in WordPress core development, head over to Trac, <a href=\"https://core.trac.wordpress.org/report/6\">pick a ticket</a>, and join the conversation in the <a href=\"https://wordpress.slack.com/archives/C02RQBWTW\">#core</a> channel. Need help? Check out the <a href=\"https://make.wordpress.org/core/handbook/\">Core Contributor Handbook</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Props to <a href=\"https://profiles.wordpress.org/ehtis/\">Ehtisham Siddiqui</a>, <a href=\"https://profiles.wordpress.org/lancewillett/\">Lance Willett</a>, <a href=\"https://profiles.wordpress.org/westonruter/\">Weston Ruter</a>, and <a href=\"https://profiles.wordpress.org/adamsilverstein/\">Adam Silverstein</a> for proofreading.</em></p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"21717\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:54:\"Students Built 108 Websites in Two Weeks in Bangladesh\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://wordpress.org/news/2026/09/108-student-websites/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 07 Sep 2026 23:19:34 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"Education\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21627\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:345:\"In July, students at two campuses in Kishoreganj, Bangladesh, built 108 websites. In eastern Uganda, a workshop that arrived to find no electricity at the school ran anyway, for more than 100 learners, because a former student had asked for it. In Costa Rica, three university students taught a three-session WordPress class to 40 high [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Destiny Kanno\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:14327:\"\n<p class=\"wp-block-paragraph\">In July, students at two campuses in Kishoreganj, Bangladesh, built 108 websites. In eastern Uganda, a workshop that arrived to find no electricity at the school ran anyway, for more than 100 learners, because a former student had asked for it. In Costa Rica, three university students taught a three-session WordPress class to 40 high schoolers, then wrote down exactly how they did it so anyone else could run the same class. None of these students paid to take part, and most had never built a website before.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Those workshops came out of two programs. WordPress Campus Connect brings free, hands-on WordPress sessions to schools and universities, run by local volunteers working from a shared curriculum. WordPress Credits goes further, placing students in mentored internships where they contribute to WordPress itself and earn academic credit for the work. Credits passed 226 graduates in July, up from 199 in June, and now works with 38 partner institutions across 16 countries.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What the Students Built</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The Kishoreganj series was organized by <a href=\"https://profiles.wordpress.org/devmuhib/\">Muhibul Haque</a>, who brought Campus Connect to two institutions two weeks apart. Students at <a href=\"https://events.wordpress.org/campusconnect/2026/kishoreganj/\">Kishoreganj University</a> built 38 sites in the first session. At Kishoreganj Polytechnic Institute, where guest speaker <a href=\"https://profiles.wordpress.org/shiponkarmakar/\">Shipon Karmakar</a> traveled more than 80 kilometers to attend, they built nearly 70 more. The <a href=\"https://events.wordpress.org/campusconnect/2026/kishoreganj/success-stories/\">success stories page</a> for the series counts more than 150 participating students so far, with two further institutions still to come.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A workshop in Spain took a different route to the same result. <a href=\"https://profiles.wordpress.org/josepmoran/\">Josep Morán</a> ran two four-hour sessions for 100 vocational students at Escola Pia Sta. Anna in Mataró, who used Playground and AI assistance to build a working plugin that calculates the best time for shore fishing in the city. Students and faculty pointed to the same two takeaways afterward: the certificate they received, and the fact that the skills map onto jobs that exist locally.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Workshop Without Power</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Bulamogi College Gadumire is on the list of Campus Connect schools in eastern Uganda because of Mariam Nairuba. At an event in Kaliro last December, she asked organizer <a href=\"https://profiles.wordpress.org/mosescursor/\">Moses Ssebunya</a> whether the program could come to her former school. She handled the arrangements with the administration herself, and on July 29 she navigated the team there. More than 100 learners were waiting. So was the school&#8217;s Director of Studies, who learned that day there was no electricity.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The team had brought laptops, a projector, and extension cables, none of which were useful now. Rather than cancel, they put two questions to the room instead: what do you already know about WordPress, and what would you like to know? &#8220;The room exploded,&#8221; the organizers wrote in their <a href=\"https://events.wordpress.org/campusconnect/2026/central-eastern-ug/gadu-maya-wordpress-campus-connect-finds-a-home-at-bulamogi-college-gadumire/\">recap of the day</a>. Students asked whether WordPress was free, how secure WordPress sites really are, and whether they could become developers themselves. John Wayera, one of two first-time volunteers alongside Nairuba, wrote the questions up on the blackboard as they came. The team copied down every answer. Before they left, they presented the school with a Certificate of Appreciation, which the Head Teacher received in front of the governing body.</p>\n\n\n\n<figure data-wp-context=\"{&quot;galleryId&quot;:&quot;6af1ad9ca3475&quot;}\" data-wp-interactive=\"core/gallery\" class=\"wp-block-gallery alignwide has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure data-wp-context=\"{&quot;imageId&quot;:&quot;6af1ad9ca389c&quot;}\" data-wp-interactive=\"core/image\" data-wp-key=\"6af1ad9ca389c\" class=\"wp-block-image size-large is-resized wp-lightbox-container\"><img data-recalc-dims=\"1\" loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" data-wp-class--hide=\"state.isContentHidden\" data-wp-class--show=\"state.isContentVisible\" data-wp-init=\"callbacks.setButtonStyles\" data-wp-on--click=\"actions.showLightbox\" data-wp-on--load=\"callbacks.setButtonStyles\" data-wp-on--pointerdown=\"actions.preloadImage\" data-wp-on--pointerenter=\"actions.preloadImageWithDelay\" data-wp-on--pointerleave=\"actions.cancelPreload\" data-wp-on-window--resize=\"callbacks.setButtonStyles\" data-id=\"21628\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/09/image.png?resize=1024%2C576&#038;ssl=1\" alt=\"\" class=\"wp-image-21628\" style=\"width:624px;height:auto\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/09/image.png?resize=1024%2C576&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/09/image.png?resize=300%2C169&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/09/image.png?resize=768%2C432&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/09/image.png?w=1200&amp;ssl=1 1200w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /><button\n			class=\"lightbox-trigger\"\n			type=\"