n      <!-- Duplirani set stavki za beskona\\u010dni (infinite) loop na manjim ekranima -->\\n      <div class=\\\"ticker-item\\\">Lasersko Se\\u010denje <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">Lasersko Graviranje <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">Fiber Laser 6KW <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">CO2 Graviranje <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">Industrijsko Obele\\u017eavanje <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">CNC Obrada <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">Savijanje Lima <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n    <\\/div>\\n  <\\/div>\\n\\n<\\/body>\\n<\\/html>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false,\"styles\":{\"e-01fb3b0\":{\"id\":\"e-01fb3b0\",\"label\":\"local\",\"type\":\"class\",\"variants\":[{\"meta\":{\"breakpoint\":\"desktop\",\"state\":null},\"props\":{\"background\":{\"$$type\":\"background\",\"value\":{\"color\":{\"$$type\":\"color\",\"value\":\"#000000\"}}},\"flex-direction\":{\"$$type\":\"string\",\"value\":\"column\"}},\"custom_css\":null}]}},\"version\":\"0.0\"},{\"id\":\"8438f1f\",\"elType\":\"e-flexbox\",\"settings\":{\"classes\":{\"$$type\":\"classes\",\"value\":[\"e-fed8793\"]}},\"elements\":[{\"id\":\"dfe010b\",\"elType\":\"e-flexbox\",\"settings\":{\"classes\":{\"$$type\":\"classes\",\"value\":[\"e-8a2a021\"]}},\"elements\":[{\"id\":\"37875af\",\"elType\":\"widget\",\"settings\":{\"image\":{\"$$type\":\"image\",\"value\":{\"src\":{\"$$type\":\"image-src\",\"value\":{\"id\":{\"$$type\":\"image-attachment-id\",\"value\":70},\"url\":null}}}},\"link\":{\"$$type\":\"link\",\"value\":{\"isTargetBlank\":null}}},\"elements\":[],\"widgetType\":\"e-image\",\"version\":