   gap: 24px;\\n      font-size: 13px;\\n      font-weight: 700;\\n      letter-spacing: 1.5px;\\n      text-transform: uppercase;\\n      color: #94a3b8;\\n      transition: color 0.3s ease;\\n      cursor: pointer;\\n    }\\n\\n    .ticker-item:hover {\\n      color: #00e5ff;\\n    }\\n\\n    \\/* Romboidni separator (ikonica iz dizajna) *\\/\\n    .ticker-separator {\\n      width: 8px;\\n      height: 8px;\\n      background-color: #00e5ff;\\n      transform: rotate(45deg);\\n      display: inline-block;\\n      box-shadow: 0 0 8px rgba(0, 229, 255, 0.6);\\n    }\\n\\n    \\/* Responzivna animacija za mobilne i manje ekrane *\\/\\n    @media (max-width: 1200px) {\\n      .ticker-track {\\n        animation: scrollTicker 25s linear infinite;\\n      }\\n\\n      .ticker-bar:hover .ticker-track {\\n        animation-play-state: paused; \\/* Pauzira na hover *\\/\\n      }\\n    }\\n\\n    @keyframes scrollTicker {\\n      0% {\\n        transform: translateX(0);\\n      }\\n      100% {\\n        transform: translateX(-50%);\\n      }\\n    }\\n  <\\/style>\\n<\\/head>\\n<body>\\n\\n  <div class=\\\"ticker-bar\\\">\\n    <div class=\\\"ticker-track\\\">\\n      <!-- Prvi set stavki -->\\n      <div class=\\\"ticker-item\\\">Lasersko Se\\u010denje <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">Lasersko Graviranje <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">Fiber Laser 6KW <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">CO2 Graviranje <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">Industrijsko Obele\\u017eavanje <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">CNC Obrada <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n      <div class=\\\"ticker-item\\\">Savijanje Lima <span class=\\\"ticker-separator\\\"><\\/span><\\/div>\\n\