uci i posla\\u0107emo vam email za slanje fajla.\\n  <\\/p>\\n<\\/div>\\n<style>\\n    @import url(\'https:\\/\\/fonts.googleapis.com\\/css2?family=Outfit:wght@400;600;700&display=swap\');\\n\\n.tip-box {\\n  width: 100%;\\n  max-width: 464px;\\n  background-color: #0b0f17;\\n  border: 1px solid rgba(255, 255, 255, 0.08);\\n  border-radius: 8px;\\n  padding: 24px 30px;\\n  box-sizing: border-box;\\n  font-family: \'Outfit\', sans-serif;\\n}\\n\\n.tip-title {\\n  font-size: 13px;\\n  font-weight: 700;\\n  color: #00e5ff;\\n  letter-spacing: 2px;\\n  margin-bottom: 12px;\\n}\\n\\n.tip-text {\\n  font-size: 14px;\\n  font-weight: 400;\\n  color: #94a3b8;\\n  line-height: 1.6;\\n  margin: 0;\\n}\\n\\n\\/* Responzivnost za manje ure\\u0111aje *\\/\\n@media (max-width: 480px) {\\n  .tip-box {\\n    padding: 20px;\\n  }\\n  \\n  .tip-text {\\n    font-size: 13px;\\n  }\\n}\\n<\\/style>\",\"_padding\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false,\"styles\":{\"e-8959188\":{\"id\":\"e-8959188\",\"label\":\"local\",\"type\":\"class\",\"variants\":[{\"meta\":{\"breakpoint\":\"desktop\",\"state\":null},\"props\":{\"width\":{\"$$type\":\"size\",\"value\":{\"size\":50,\"unit\":\"%\"}},\"flex-direction\":{\"$$type\":\"string\",\"value\":\"column\"}},\"custom_css\":null},{\"meta\":{\"breakpoint\":\"mobile\",\"state\":null},\"props\":{\"width\":{\"$$type\":\"size\",\"value\":{\"size\":100,\"unit\":\"%\"}}},\"custom_css\":null},{\"meta\":{\"breakpoint\":\"tablet\",\"state\":null},\"props\":{\"width\":{\"$$type\":\"size\",\"value\":{\"size\":100,\"unit\":\"%\"}}},\"custom_css\":null}]}},\"version\":\"0.0\"},{\"id\":\"ad16396\",\"elType\":\"e-flexbox\",\"settings\":{\"classes\":{\"$$type\":\"classes\",\"value\":[\"e-e782caf\"]}},\"elements\":[{\"id\":\"88899d6\",\"elType\":\"widget\",\"settings\":{\"html\":\"<div class=\\\"inquiry-form\\\">\\n  <div class=\\\"form-tag\\\">