INSERT INTO `wp_posts` VALUES (24,1,'2026-11-04 10:21:09','2026-11-04 10:21:09','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-546f9acb .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-546f9acb .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-546f9acb .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-546f9ac