t: 700;\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      color: #94a3b8;\n      transition: color 0.3s ease;\n      cursor: pointer;\n    }\n    .ticker-item:hover {\n      color: #00e5ff;\n    }\n    /* Romboidni separator (ikonica iz dizajna) */\n    .ticker-separator {\n      width: 8px;\n      height: 8px;\n      background-color: #00e5ff;\n      transform: rotate(45deg);\n      display: inline-block;\n      box-shadow: 0 0 8px rgba(0, 229, 255, 0.6);\n    }\n    /* Responzivna animacija za mobilne i manje ekrane */\n    @media (max-width: 1200px) {\n      .ticker-track {\n        animation: scrollTicker 25s linear infinite;\n      }\n      .ticker-bar:hover .ticker-track {\n        animation-play-state: paused; /* Pauzira na hover */\n      }\n    }\n    @keyframes scrollTicker {\n      0% {\n        transform: translateX(0);\n      }\n      100% {\n        transform: translateX(-50%);\n      }\n    }\n  </style>\n</head>\n<body>\n      <!-- Prvi set stavki -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n      <!-- Duplirani set stavki za beskonačni (infinite) loop na manjim ekranima -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n</body>\n</html>		<p>Imate crtez? Mi imamo laser</p>			<p data-interaction-id=\"d3dd46d\">Pošaljite nam DXF, DWG ili PDF fajl i dobijte ponudu u roku od par sati.</p>\n										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path>