t: 700;\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      color: #94a3b8;\n      transition: color 0.3s ease;\n      cursor: pointer;\n    }\n    .ticker-item:hover {\n      color: #00e5ff;\n    }\n    /* Romboidni separator (ikonica iz dizajna) */\n    .ticker-separator {\n      width: 8px;\n      height: 8px;\n      background-color: #00e5ff;\n      transform: rotate(45deg);\n      display: inline-block;\n      box-shadow: 0 0 8px rgba(0, 229, 255, 0.6);\n    }\n    /* Responzivna animacija za mobilne i manje ekrane */\n    @media (max-width: 1200px) {\n      .ticker-track {\n        animation: scrollTicker 25s linear infinite;\n      }\n      .ticker-bar:hover .ticker-track {\n        animation-play-state: paused; /* Pauzira na hover */\n      }\n    }\n    @keyframes scrollTicker {\n      0% {\n        transform: translateX(0);\n      }\n      100% {\n        transform: translateX(-50%);\n      }\n    }\n  </style>\n</head>\n<body>\n      <!-- Prvi set stavki -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n      <!-- Duplirani set stavki za beskonačni (infinite) loop na manjim ekranima -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n</body>\n</html>					<img data-interaction-id=\"37875af\" id=\"70\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png\" width=\"616\" height=\"444\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png 616w, http://mihamiha.local/wp-content/uploads/2026/11/onama-300x216.png 300w\" alt=\"\"/>					<h1 data-interaction-id=\"c612355\">Spoj Tehnologije, Iskustva i Strasti<br>prema Metalu</h1>\n		<p>Imate crtez? Mi imamo laser</p>			<p data-interaction-id=\"d3dd46d\">Pošaljite nam DXF, DWG ili PDF fajl i dobijte ponudu u roku od