ael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n									<!DOCTYPE html>\n<html lang=\"sr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Services Ticker Bar</title>\n  <!-- Uvoz Outfit fonta sa Google Fonts -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n    }\n    body {\n      font-family: \'Outfit\', sans-serif;\n    }\n    /* Glavni kontejner trake */\n    .ticker-bar {\n      width: 100%;\n      height: 54px;\n      background-color: #0d111a;\n      border-top: 1px solid rgba(255, 255, 255, 0.1);\n      border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n      display: flex;\n      align-items: center;\n      overflow: hidden;\n      white-space: nowrap;\n      position: relative;\n    }\n    /* Sadržaj trake koji se ponavlja/scroll-uje */\n    .ticker-track {\n      display: flex;\n      align-items: center;\n      gap: 24px;\n      padding: 0 16px;\n      width: max-content;\n    }\n    /* Pojedinačna stavka */\n    .ticker-item {\n      display: inline-flex;\n      align-items: center;\n      gap: 24px;\n      font-size: 13px;\n      font-weight: 700;\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      color: #94a3b8;\n      transition: color 0.3s ease;\n      cursor: pointer;\n    }\n    .ticker-item:hover {\n      color: #00e5ff;\n    }\n    /* Romboidni separator (ikonica iz dizajna) */\n    .ticker-separator {\n      width: 8px;\n      height: 8px;\n      background-color: #00e5ff;\n      transform: rotate(45deg);\n      display: inline-block;\n      box-shadow: 0 0 8px rgba(0, 229, 255, 0.6);\n    }\n    /* Responzivna animacija za mobilne i manje ekrane */\n    @media (max-width: 1200px) {\n      .ticker-track {\n        animation: scrollTicker 25s linear infinite;\n      }\n      .ticker-bar:hover .ticker-track {\n        animation-play-state: paused; /* Pauzira na hover */\n      }\n    }\n    @keyframes scrollTicker {\n      0% {\n        transform: translateX(0);\n      }\n      100% {\n        transform: translateX(-50%);\n      }\n    }\n  </style>\n</head>\n<body>\n      <!-- Prvi set stavki -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n      <!-- Duplirani set stavki za beskonačni (infinite) loop na manjim ekranima -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n</body>\n</html>					<img data-interaction-id=\"37875af\" id=\"70\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png\" width=\"616\" height=\"444\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png 616w, http://mihamiha.local/wp-content/uploads/2026/11/onama-300x216.png 300w\" alt=\"\"/>					<h2 data-interaction-id=\"c612355\">Spoj Tehnologije, Iskustva i Strasti<br>prema Metalu</h2>\n					<p data-interaction-id=\"8af860f\">Miha Laser je pouzdan partner za industrijska preduzeća, arhitekte, dizajnere i<br>pojedince. Nudimo kompletnu uslugu sečenja i graviranja uz podršku za tehničku<br>pripremu fajlova.</p>\n							<ul>\n							<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Fiber laser najnovije generacije za metale do 20mm debljine\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										CO2 laser za besprekorno graviranje drveta, pleksiglasa i kože\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Kontrola kvaliteta svakog komada pre isporuke\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Pomoć pri izradi CAD modela i optimizaciji utroška materijala\n									</li>\n						</ul>\n				<p>Imate crtez? Mi imamo laser</p>			<p data-interaction-id=\"d3dd46d\">Pošaljite nam DXF, DWG ili PDF fajl i dobijte ponudu u roku od par sati.</p>\n										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Zatražite Ponudu\n					</a>\n									<img data-interaction-id=\"492b45b\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"#\">\n						X-twitter\n						<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M389.2 48h70.6L305.6 224.2 487 464H345L233.7 318.6 106.5 464H35.8L200.7 275.5 26.8 48H172.4L272.9 180.9 389.2 48zM364.4 421.8h39.1L151.1 88h-42L364.4 421.8z\"></path></svg>					</a>\n					<a href=\"#\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>					</a>\n					<a href=\"#\">\n						Linkedin-in\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M100.28 448H7.4V148.9h92.88zM53.79 108.1C24.09 108.1 0 83.5 0 53.8a53.79 53.79 0 0 1 107.58 0c0 29.7-24.1 54.3-53.79 54.3zM447.9 448h-92.68V302.4c0-34.7-.7-79.2-48.29-79.2-48.29 0-55.6