INSERT INTO `wp_posts` VALUES (161,1,'2026-11-04 13:10:10','2026-11-04 13:10:10','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n									<!DOCTYPE html>\n<html lang=\"sr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Services Ticker Bar</title>\n  <!-- Uvoz Outfit fonta sa Google Fonts -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n    }\n    body {\n      font-family: \'Outfit\', sans-serif;\n    }\n    /* Glavni kontejner trake */\n    .ticker-bar {\n      width: 100%;\n      height: 54px;\n      background-color: #0d111a;\n      border-top: 1px solid rgba(255, 255, 255, 0.1);\n      border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n      display: flex;\n      align-items: center;\n      overflow: hidden;\n      white-space: nowrap;\n      position: relative;\n    }\n    /* Sadržaj trake koji se ponavlja/scroll-uje */\n    .ticker-track {\n      display: flex;\n      align-items: center;\n      gap: 24px;\n      padding: 0 16px;\n      width: max-content;\n    }\n    /* Pojedinačna stavka */\n    .ticker-item {\n      display: inline-flex;\n      align-items: center;\n      gap: 24px;\n      font-size: 13px;\n      font-weight: 700;\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      color: #94a3b8;\n      transition: color 0.3s ease;\n      cursor: pointer;\n    }\n    .ticker-item:hover {\n      color: #00e5ff;\n    }\n    /* Romboidni separator (ikonica iz dizajna) */\n    .ticker-separator {\n      width: 8px;\n      height: 8px;\n      background-color: #00e5ff;\n      transform: rotate(45deg);\n      display: inline-block;\n      box-shadow: 0 0 8px rgba(0, 229, 255, 0.6);\n    }\n    /* Responzivna animacija za mobilne i manje ekrane */\n    @media (max-width: 1200px) {\n      .ticker-track {\n        animation: scrollTicker 25s linear infinite;\n      }\n      .ticker-bar:hover .ticker-track {\n        animation-play-state: paused; /* Pauzira na hover */\n      }\n    }\n    @keyframes scrollTicker {\n      0% {\n        transform: translateX(0);\n      }\n      100% {\n        transform: translateX(-50%);\n      }\n    }\n  </style>\n</head>\n<body>\n      <!-- Prvi set stavki -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n      <!-- Duplirani set stavki za beskonačni (infinite) loop na manjim ekranima -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n</body>\n</html>					<p data-interaction-id=\"f74c5c5\">// KAKO RADIMO</p>\n					<h2 data-interaction-id=\"c07ecac\">4 Koraka od Crteža do Gotovog Proizvoda</h2>\n					01\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"4b7e3d9\">Slanje upita i CAD fajla</h2>\n					<p data-interaction-id=\"2770fad\">Pošaljite crtež u DXF, DWG ili PDF<br>formatu sa željenim debljinama i<br>količinom.</p>\n					02\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"5d9f438\">Analiza i Ponuda</h2>\n					<p data-interaction-id=\"f76d4f9\">Optimizujemo kretanje lasera i šaljemo najpovoljniju ponudu u roku od par sati.</p>\n					03\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"c66a3e4\">Laserska Obrada</h2>\n					<p data-interaction-id=\"4b56d36\">Sečenje i graviranje na visokopreciznim CNC fiber mašinama uz stalni nadzor.</p>\n					04\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"f5f3e1b\">Kontrola i Isporuka</h2>\n					<p data-interaction-id=\"3b92bdf\">Svaki komad prolazi proveru dimenzija pre pakovanja i slanja ili preuzimanja.</p>\n					<img data-interaction-id=\"37875af\" id=\"70\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png\" width=\"616\" height=\"444\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png 616w, http://mihamiha.local/wp-content/uploads/2026/11/onama-300x216.png 300w\" alt=\"\"/>					<p data-interaction-id=\"edda545\">// ZAŠTO MI</p>\n					<h3 data-interaction-id=\"c612355\">Spoj Tehnologije, Iskustva i Strasti prema Metalu</h3>\n					<p data-interaction-id=\"8af860f\">Miha Laser je pouzdan partner za industrijska preduzeća, arhitekte, dizajnere i pojedince. Nudimo kompletnu uslugu sečenja i graviranja uz podršku za tehničku<br>pripremu fajlova.</p>\n							<ul>\n							<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-5