INSERT INTO `wp_posts` VALUES (191,1,'2026-11-04 13:19:40','2026-11-04 13:19:40','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n									<!DOCTYPE html>\n<html lang=\"sr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Services Ticker Bar</title>\n  <!-- Uvoz Outfit fonta sa Google Fonts -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n    }\n    body {\n      font-family: \'Outfit\', sans-serif;\n    }\n    /* Glavni kontejner trake */\n    .ticker-bar {\n      width: 100%;\n      height: 54px;\n      background-color: #0d111a;\n      border-top: 1px solid rgba(255, 255, 255, 0.1);\n      border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n      display: flex;\n      align-items: center;\n      overflow: hidden;\n      white-space: nowrap;\n      position: relative;\n    }\n    /* Sadržaj trake koji se ponavlja/scroll-uje */\n    .ticker-track {\n      display: flex;\n      align-items: center;\n      gap: 24px;\n      padding: 0 16px;\n      width: max-content;\n    }\n    /* Pojedinačna stavka */\n    .ticker-item {\n      display: inline-flex;\n      align-items: center;\n      gap: 24px;\n      font-size: 13px;\n      font-weight: 700;\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      color: #94a3b8;\n      transition: color 0.3s ease;\n      cursor: pointer;\n    }\n    .ticker-item:hover {\n      color: #00e5ff;\n    }\n    /* Romboidni separator (ikonica iz dizajna) */\n    .ticker-separator {\n      width: 8px;\n      height: 8px;\n      background-color: #00e5ff;\n      transform: rotate(45deg);\n      display: inline-block;\n      box-shadow: 0 0 8px rgba(0, 229, 255, 0.6);\n    }\n    /* Responzivna animacija za mobilne i manje ekrane */\n    @media (max-width: 1200px) {\n      .ticker-track {\n        animation: scrollTicker 25s linear infinite;\n      }\n      .ticker-bar:hover .ticker-track {\n        animation-play-state: paused; /* Pauzira na hover */\n      }\n    }\n    @keyframes scrollTicker {\n      0% {\n        transform: translateX(0);\n      }\n      100% {\n        transform: translateX(-50%);\n      }\n    }\n  </style>\n</head>\n<body>\n      <!-- Prvi set stavki -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n      <!-- Duplirani set stavki za beskonačni (infinite) loop na manjim ekranima -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n</body>\n</html>					<p data-interaction-id=\"ad1294f\">// USLUGE</p>\n					<h2 data-interaction-id=\"bfa24f5\">Kompletna Ponuda Laserskih i CNC<br>Usluga</h2>\n										<a href=\"/usluge\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Sve usluge\n					</a>\n																			<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge.png\" alt=\"\" />																<p data-interaction-id=\"c96585c\">Fiber Laser 6kW</p>\n					<h2 data-interaction-id=\"800d1ef\">Lasersko Sečenje Metala</h2>\n					<p data-interaction-id=\"1117b55\">Visokoefikasno fiber sečenje crnog lima,<br>inoksa, aluminijuma i mesinga čistih ivica bez<br>potrebe za dodatnom obradom. Idealno za…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge.png\" alt=\"\" />																<p data-interaction-id=\"f777c5e\">Fiber Laser 6kW</p>\n					<h2 data-interaction-id=\"db15816\">Lasersko Sečenje Metala</h2>\n					<p data-interaction-id=\"d80653a\">Visokoefikasno fiber sečenje crnog lima,<br>inoksa, aluminijuma i mesinga čistih ivica bez<br>potrebe za dodatnom obradom. Idealno za…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge.png\" alt=\"\" />																<p data-interaction-id=\"77dde52\">Fiber Laser 6kW</p>\n					<h2 data-interaction-id=\"55fce89\">Lasersko Sečenje Metala</h2>\n					<p data-interaction-id=\"51f3466\">Visokoefikasno fiber sečenje crnog lima,<br>inoksa, aluminijuma i mesinga čistih ivica bez<br>potrebe za dodatnom obradom. Idealno za…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge.png\" alt=\"\" />																<p data-interaction-id=\"1c0065f\">Fiber Laser 6kW</p>\n					<h2 data-interaction-id=\"9ee5c28\">Lasersko Sečenje Metala</h2>\n					<p data-interaction-id=\"7f1b60c\">Visokoefikasno fiber sečenje crnog lima,<br>inoksa, aluminijuma i mesinga čistih ivica bez<br>potrebe za dodatnom obradom. Idealno za…</p>\n					<p data-interaction-id=\"f74c5c5\">// KAKO RADIMO</p>\n					<h2 data-interaction-id=\"c07ecac\">4 Koraka od Crteža do Gotovog Proizvoda</h2>\n					01\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"4b7e3d9\">Slanje upita i CAD fajla</h2>\n					<p data-interaction-id=\"2770fad\">Pošaljite crtež u DXF, DWG ili PDF<br>formatu sa željenim debljinama i<br>količinom.</p>\n					02\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"5d9f438\">Analiza i Ponuda</h2>\n					<p data-interaction-id=\"f76d4f9\">Optimizujemo kretanje lasera i šaljemo najpovoljniju ponudu u roku od par sati.</p>\n					03\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"c66a3e4\">Laserska Obrada</h2>\n					<p data-interaction-id=\"4b56d36\">Sečenje i graviranje na visokopreciznim CNC fiber mašinama uz stalni nadzor.</p>\n					04\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"f5f3e1b\">Kontrola i Isporuka</h2>\n					<p data-interaction-id=\"3b92bdf\">Svaki komad prolazi proveru dimenzija pre pakovanja i slanja ili preuzimanja.</p>\n					<img data-interaction-id=\"37875af\" id=\"70\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png\" width=\"616\" height=\"444\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png 616w, http://mihamiha.local/wp-content/uploads/2026/11/onama-300x216.png 300w\" alt=\"\"/>					<p data-interaction-id=\"edda545\">// ZAŠTO MI</p>\n					<h3 data-interaction-id=\"c612355\">Spoj Tehnologije, Iskustva i Strasti prema Metalu</h3>\n					<p data-interaction-id=\"8af860f\">Miha Laser je pouzdan partner za industrijska preduzeća, arhitekte, dizajnere i pojedince. Nudimo kompletnu uslugu sečenja i graviranja uz podršku za tehničku<br>pripremu fajlova.</p>\n							<ul>\n							<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Fiber laser najnovije generacije za metale do 20mm debljine\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										CO2 laser za besprekorno graviranje drveta, pleksiglasa i kože\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Kontrola kvaliteta svakog komada pre isporuke\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Pomoć pri izradi CAD modela i optimizaciji utroška materijala\n									</li>\n						</ul>\n												<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Više o nama\n					</a>\n						<p>Imate crtez? Mi imamo laser</p>			<p data-interaction-id=\"d3dd46d\">Pošaljite nam DXF, DWG ili PDF fajl i dobijte ponudu u roku od par sati.</p>\n										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Zatražite Ponudu\n					</a>\n									<img data-interaction-id=\"492b45b\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"#\">\n						X-twitter\n						<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M389.2 48h70.6L305.6 224.2 487 464H345L233.7 318.6 106.5 464H35.8L200.7 275.5 26.8 48H172.4L272.9 180.9 389.2 48zM364.4 421.8h39.1L151.1 88h-42L364.4 421.8z\"></path></svg>					</a>\n					<a href=\"#\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>					</a>\n					<a href=\"#\">\n						Linkedin-in\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M100.28 448H7.4V148.9h92.88zM53.79 108.1C24.09 108.1 0 83.5 0 53.8a53.79 53.79 0 0 1 107.58 0c0 29.7-24.1 54.3-53.79 54.3zM447.9 448h-92.68V302.4c0-34.7-.7-79.2-48.29-79.2-48.29 0-55.69 37.7-55.69 76.7V448h-92.78V148.9h89.08v40.8h1.3c12.4-23.5 42.69-48.3 87.88-48.3 94 0 111.28 61.9 111.28 142.3V448z\"></path></svg>					</a>\n							<h3>Navigacija</h3>							<ul>\n							<li>\n											<a href=\"http://pocetna\">\n											Početna\n											</a>\n									</li>\n								<li>\n											<a href=\"/o-nama\">\n											O nama\n											</a>\n									</li>\n								<li>\n											<a href=\"/usluge\">\n											Usluge\n											</a>\n									</li>\n								<li>\n											<a href=\"/galerija\">\n											Galerija\n											</a>\n									</li>\n								<li>\n											<a href=\"/kontakt\">\n											Kontakt\n											</a>\n									</li>\n						</ul>\n							<h3>Kontakt</h3>							<ul>\n							<li>\n											<a href=\"#\">\n											+381 64 123 4567\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											info@mihalaser.rs\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Industrijska zona bb, 11000 Beograd, Srbija\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Pon - Pet: 08:00 - 17:00 | Sub: 08:00 - 14:00\n											</a>\n									</li>\n						</ul>\n							<p>© 2026 Miha Laser — Laserske usluge. Sva prava zadržana.</p>','Pocetna','','inherit','closed','closed','','7-revision-v1','','','2026-11-04 13:19:40','2026-11-04 13:19:40','',7,'http://mihamiha.local/?p=191',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (192,1,'2026-11-04 13:19:40','2026-11-04 13:19:40','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n									<!DOCTYPE html>\n<html lang=\"sr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Services Ticker Bar</title>\n  <!-- Uvoz Outfit fonta sa Google Fonts -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n    }\n    body {\n      font-family: \'Outfit\', sans-serif;\n    }\n    /* Glavni kontejner trake */\n    .ticker-bar {\n      width: 100%;\n      height: 54px;\n      background-color: #0d111a;\n      border-top: 1px solid rgba(255, 255, 255, 0.1);\n      border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n      display: flex;\n      align-items: center;\n      overflow: hidden;\n      white-space: nowrap;\n      position: relative;\n    }\n    /* Sadržaj trake koji se ponavlja/scroll-uje */\n    .ticker-track {\n      display: flex;\n      align-items: center;\n      gap: 24px;\n      padding: 0 16px;\n      width: max-content;\n    }\n    /* Pojedinačna stavka */\n    .ticker-item {\n      display: inline-flex;\n      align-items: center;\n      gap: 24px;\n      font-size: 13px;\n      font-weight: 700;\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      color: #94a3b8;\n      transition: color 0.3s ease;\n      cursor: pointer;\n    }\n    .ticker-item:hover {\n      color: #00e5ff;\n    }\n    /* Romboidni separator (ikonica iz dizajna) */\n    .ticker-separator {\n      width: 8px;\n      height: 8px;\n      background-color: #00e5ff;\n      transform: rotate(45deg);\n      display: inline-block;\n      box-shadow: 0 0 8px rgba(0, 229, 255, 0.6);\n    }\n    /* Responzivna animacija za mobilne i manje ekrane */\n    @media (max-width: 1200px) {\n      .ticker-track {\n        animation: scrollTicker 25s linear infinite;\n      }\n      .ticker-bar:hover .ticker-track {\n        animation-play-state: paused; /* Pauzira na hover */\n      }\n    }\n    @keyframes scrollTicker {\n      0% {\n        transform: translateX(0);\n      }\n      100% {\n        transform: translateX(-50%);\n      }\n    }\n  </style>\n</head>\n<body>\n      <!-- Prvi set stavki -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n      <!-- Duplirani set stavki za beskonačni (infinite) loop na manjim ekranima -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n</body>\n</html>					<p data-interaction-id=\"ad1294f\">// USLUGE</p>\n					<h2 data-interaction-id=\"bfa24f5\">Kompletna Ponuda Laserskih i CNC<br>Usluga</h2>\n										<a href=\"/usluge\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Sve usluge\n					</a>\n																			<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge.png\" alt=\"\" />																<p data-interaction-id=\"c96585c\">Fiber Laser 6kW</p>\n					<h2 data-interaction-id=\"800d1ef\">Lasersko Sečenje Metala</h2>\n					<p data-interaction-id=\"1117b55\">Visokoefikasno fiber sečenje crnog lima,<br>inoksa, aluminijuma i mesinga čistih ivica bez<br>potrebe za dodatnom obradom. Idealno za…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge2.png\" alt=\"\" />																<p data-interaction-id=\"f777c5e\">CO2 &amp; Fiber Marker</p>\n					<h2 data-interaction-id=\"db15816\">Lasersko Graviranje</h2>\n					<p data-interaction-id=\"d80653a\">Precizno graviranje logotipa, natpisa, tekstura<br>i serijskih oznaka na drvetu, pleksiglasu, akrilu,<br>koži i metalu. Od reklamne galanterije do…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge3.png\" alt=\"\" />																<p data-interaction-id=\"77dde52\">Fiber Marker</p>\n					<h2 data-interaction-id=\"55fce89\">Industrijsko Obeležavanje</h2>\n					<p data-interaction-id=\"51f3466\">Trajno obeležavanje mašinskih delova, alata,<br>industrijskih tablica, QR kodova i serijskih<br>brojeva na metalu. Obeležja otporna na…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge4.png\" alt=\"\" />																<p data-interaction-id=\"1c0065f\">CNC Glodalica &amp; Apkan</p>\n					<h2 data-interaction-id=\"9ee5c28\">CNC Obrada &amp; Savijanje</h2>\n					<p data-interaction-id=\"7f1b60c\">Dodatna obrada, CNC glodanje, savijanje na<br>apkan presi i izrada kompletnih sklopova po<br>vašem nacrtu. Kompletna završna obrada do</p>\n					<p data-interaction-id=\"f74c5c5\">// KAKO RADIMO</p>\n					<h2 data-interaction-id=\"c07ecac\">4 Koraka od Crteža do Gotovog Proizvoda</h2>\n					01\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"4b7e3d9\">Slanje upita i CAD fajla</h2>\n					<p data-interaction-id=\"2770fad\">Pošaljite crtež u DXF, DWG ili PDF<br>formatu sa željenim debljinama i<br>količinom.</p>\n					02\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"5d9f438\">Analiza i Ponuda</h2>\n					<p data-interaction-id=\"f76d4f9\">Optimizujemo kretanje lasera i šaljemo najpovoljniju ponudu u roku od par sati.</p>\n					03\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"c66a3e4\">Laserska Obrada</h2>\n					<p data-interaction-id=\"4b56d36\">Sečenje i graviranje na visokopreciznim CNC fiber mašinama uz stalni nadzor.</p>\n					04\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"f5f3e1b\">Kontrola i Isporuka</h2>\n					<p data-interaction-id=\"3b92bdf\">Svaki komad prolazi proveru dimenzija pre pakovanja i slanja ili preuzimanja.</p>\n					<img data-interaction-id=\"37875af\" id=\"70\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png\" width=\"616\" height=\"444\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png 616w, http://mihamiha.local/wp-content/uploads/2026/11/onama-300x216.png 300w\" alt=\"\"/>					<p data-interaction-id=\"edda545\">// ZAŠTO MI</p>\n					<h3 data-interaction-id=\"c612355\">Spoj Tehnologije, Iskustva i Strasti prema Metalu</h3>\n					<p data-interaction-id=\"8af860f\">Miha Laser je pouzdan partner za industrijska preduzeća, arhitekte, dizajnere i pojedince. Nudimo kompletnu uslugu sečenja i graviranja uz podršku za tehničku<br>pripremu fajlova.</p>\n							<ul>\n							<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Fiber laser najnovije generacije za metale do 20mm debljine\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										CO2 laser za besprekorno graviranje drveta, pleksiglasa i kože\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Kontrola kvaliteta svakog komada pre isporuke\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Pomoć pri izradi CAD modela i optimizaciji utroška materijala\n									</li>\n						</ul>\n												<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Više o nama\n					</a>\n						<p>Imate crtez? Mi imamo laser</p>			<p data-interaction-id=\"d3dd46d\">Pošaljite nam DXF, DWG ili PDF fajl i dobijte ponudu u roku od par sati.</p>\n										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Zatražite Ponudu\n					</a>\n									<img data-interaction-id=\"492b45b\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"#\">\n						X-twitter\n						<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M389.2 48h70.6L305.6 224.2 487 464H345L233.7 318.6 106.5 464H35.8L200.7 275.5 26.8 48H172.4L272.9 180.9 389.2 48zM364.4 421.8h39.1L151.1 88h-42L364.4 421.8z\"></path></svg>					</a>\n					<a href=\"#\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>					</a>\n					<a href=\"#\">\n						Linkedin-in\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M100.28 448H7.4V148.9h92.88zM53.79 108.1C24.09 108.1 0 83.5 0 53.8a53.79 53.79 0 0 1 107.58 0c0 29.7-24.1 54.3-53.79 54.3zM447.9 448h-92.68V302.4c0-34.7-.7-79.2-48.29-79.2-48.29 0-55.69 37.7-55.69 76.7V448h-92.78V148.9h89.08v40.8h1.3c12.4-23.5 42.69-48.3 87.88-48.3 94 0 111.28 61.9 111.28 142.3V448z\"></path></svg>					</a>\n							<h3>Navigacija</h3>							<ul>\n							<li>\n											<a href=\"http://pocetna\">\n											Početna\n											</a>\n									</li>\n								<li>\n											<a href=\"/o-nama\">\n											O nama\n											</a>\n									</li>\n								<li>\n											<a href=\"/usluge\">\n											Usluge\n											</a>\n									</li>\n								<li>\n											<a href=\"/galerija\">\n											Galerija\n											</a>\n									</li>\n								<li>\n											<a href=\"/kontakt\">\n											Kontakt\n											</a>\n									</li>\n						</ul>\n							<h3>Kontakt</h3>							<ul>\n							<li>\n											<a href=\"#\">\n											+381 64 123 4567\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											info@mihalaser.rs\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Industrijska zona bb, 11000 Beograd, Srbija\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Pon - Pet: 08:00 - 17:00 | Sub: 08:00 - 14:00\n											</a>\n									</li>\n						</ul>\n							<p>© 2026 Miha Laser — Laserske usluge. Sva prava zadržana.</p>','Pocetna','','inherit','closed','closed','','7-revision-v1','','','2026-11-04 13:19:40','2026-11-04 13:19:40','',7,'http://mihamiha.local/?p=192',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (193,1,'2026-11-04 13:20:20','2026-11-04 13:20:20','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n									<!DOCTYPE html>\n<html lang=\"sr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Services Ticker Bar</title>\n  <!-- Uvoz Outfit fonta sa Google Fonts -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n    }\n    body {\n      font-family: \'Outfit\', sans-serif;\n    }\n    /* Glavni kontejner trake */\n    .ticker-bar {\n      width: 100%;\n      height: 54px;\n      background-color: #0d111a;\n      border-top: 1px solid rgba(255, 255, 255, 0.1);\n      border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n      display: flex;\n      align-items: center;\n      overflow: hidden;\n      white-space: nowrap;\n      position: relative;\n    }\n    /* Sadržaj trake koji se ponavlja/scroll-uje */\n    .ticker-track {\n      display: flex;\n      align-items: center;\n      gap: 24px;\n      padding: 0 16px;\n      width: max-content;\n    }\n    /* Pojedinačna stavka */\n    .ticker-item {\n      display: inline-flex;\n      align-items: center;\n      gap: 24px;\n      font-size: 13px;\n      font-weight: 700;\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      color: #94a3b8;\n      transition: color 0.3s ease;\n      cursor: pointer;\n    }\n    .ticker-item:hover {\n      color: #00e5ff;\n    }\n    /* Romboidni separator (ikonica iz dizajna) */\n    .ticker-separator {\n      width: 8px;\n      height: 8px;\n      background-color: #00e5ff;\n      transform: rotate(45deg);\n      display: inline-block;\n      box-shadow: 0 0 8px rgba(0, 229, 255, 0.6);\n    }\n    /* Responzivna animacija za mobilne i manje ekrane */\n    @media (max-width: 1200px) {\n      .ticker-track {\n        animation: scrollTicker 25s linear infinite;\n      }\n      .ticker-bar:hover .ticker-track {\n        animation-play-state: paused; /* Pauzira na hover */\n      }\n    }\n    @keyframes scrollTicker {\n      0% {\n        transform: translateX(0);\n      }\n      100% {\n        transform: translateX(-50%);\n      }\n    }\n  </style>\n</head>\n<body>\n      <!-- Prvi set stavki -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n      <!-- Duplirani set stavki za beskonačni (infinite) loop na manjim ekranima -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n</body>\n</html>					<p data-interaction-id=\"ad1294f\">// USLUGE</p>\n					<h2 data-interaction-id=\"bfa24f5\">Kompletna Ponuda Laserskih i CNC<br>Usluga</h2>\n										<a href=\"/usluge\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Sve usluge\n					</a>\n																			<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge.png\" alt=\"\" />																<p data-interaction-id=\"c96585c\">Fiber Laser 6kW</p>\n					<h2 data-interaction-id=\"800d1ef\">Lasersko Sečenje Metala</h2>\n					<p data-interaction-id=\"1117b55\">Visokoefikasno fiber sečenje crnog lima,<br>inoksa, aluminijuma i mesinga čistih ivica bez<br>potrebe za dodatnom obradom. Idealno za…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge2.png\" alt=\"\" />																<p data-interaction-id=\"f777c5e\">CO2 &amp; Fiber Marker</p>\n					<h2 data-interaction-id=\"db15816\">Lasersko Graviranje</h2>\n					<p data-interaction-id=\"d80653a\">Precizno graviranje logotipa, natpisa, tekstura<br>i serijskih oznaka na drvetu, pleksiglasu, akrilu,<br>koži i metalu. Od reklamne galanterije do…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge3.png\" alt=\"\" />																<p data-interaction-id=\"77dde52\">Fiber Marker</p>\n					<h2 data-interaction-id=\"55fce89\">Industrijsko Obeležavanje</h2>\n					<p data-interaction-id=\"51f3466\">Trajno obeležavanje mašinskih delova, alata,<br>industrijskih tablica, QR kodova i serijskih<br>brojeva na metalu. Obeležja otporna na…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge4.png\" alt=\"\" />																<p data-interaction-id=\"1c0065f\">CNC Glodalica &amp; Apkan</p>\n					<h2 data-interaction-id=\"9ee5c28\">CNC Obrada &amp; Savijanje</h2>\n					<p data-interaction-id=\"7f1b60c\">Dodatna obrada, CNC glodanje, savijanje na<br>apkan presi i izrada kompletnih sklopova po<br>vašem nacrtu. Kompletna završna obrada do</p>\n					<p data-interaction-id=\"f74c5c5\">// KAKO RADIMO</p>\n					<h2 data-interaction-id=\"c07ecac\">4 Koraka od Crteža do Gotovog Proizvoda</h2>\n					01\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"4b7e3d9\">Slanje upita i CAD fajla</h2>\n					<p data-interaction-id=\"2770fad\">Pošaljite crtež u DXF, DWG ili PDF<br>formatu sa željenim debljinama i<br>količinom.</p>\n					02\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"5d9f438\">Analiza i Ponuda</h2>\n					<p data-interaction-id=\"f76d4f9\">Optimizujemo kretanje lasera i šaljemo najpovoljniju ponudu u roku od par sati.</p>\n					03\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"c66a3e4\">Laserska Obrada</h2>\n					<p data-interaction-id=\"4b56d36\">Sečenje i graviranje na visokopreciznim CNC fiber mašinama uz stalni nadzor.</p>\n					04\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"f5f3e1b\">Kontrola i Isporuka</h2>\n					<p data-interaction-id=\"3b92bdf\">Svaki komad prolazi proveru dimenzija pre pakovanja i slanja ili preuzimanja.</p>\n					<img data-interaction-id=\"37875af\" id=\"70\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png\" width=\"616\" height=\"444\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png 616w, http://mihamiha.local/wp-content/uploads/2026/11/onama-300x216.png 300w\" alt=\"\"/>					<p data-interaction-id=\"edda545\">// ZAŠTO MI</p>\n					<h3 data-interaction-id=\"c612355\">Spoj Tehnologije, Iskustva i Strasti prema Metalu</h3>\n					<p data-interaction-id=\"8af860f\">Miha Laser je pouzdan partner za industrijska preduzeća, arhitekte, dizajnere i pojedince. Nudimo kompletnu uslugu sečenja i graviranja uz podršku za tehničku<br>pripremu fajlova.</p>\n							<ul>\n							<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Fiber laser najnovije generacije za metale do 20mm debljine\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										CO2 laser za besprekorno graviranje drveta, pleksiglasa i kože\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Kontrola kvaliteta svakog komada pre isporuke\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Pomoć pri izradi CAD modela i optimizaciji utroška materijala\n									</li>\n						</ul>\n												<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Više o nama\n					</a>\n						<p>Imate crtez? Mi imamo laser</p>			<p data-interaction-id=\"d3dd46d\">Pošaljite nam DXF, DWG ili PDF fajl i dobijte ponudu u roku od par sati.</p>\n										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Zatražite Ponudu\n					</a>\n									<img data-interaction-id=\"492b45b\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"#\">\n						X-twitter\n						<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M389.2 48h70.6L305.6 224.2 487 464H345L233.7 318.6 106.5 464H35.8L200.7 275.5 26.8 48H172.4L272.9 180.9 389.2 48zM364.4 421.8h39.1L151.1 88h-42L364.4 421.8z\"></path></svg>					</a>\n					<a href=\"#\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>					</a>\n					<a href=\"#\">\n						Linkedin-in\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M100.28 448H7.4V148.9h92.88zM53.79 108.1C24.09 108.1 0 83.5 0 53.8a53.79 53.79 0 0 1 107.58 0c0 29.7-24.1 54.3-53.79 54.3zM447.9 448h-92.68V302.4c0-34.7-.7-79.2-48.29-79.2-48.29 0-55.69 37.7-55.69 76.7V448h-92.78V148.9h89.08v40.8h1.3c12.4-23.5 42.69-48.3 87.88-48.3 94 0 111.28 61.9 111.28 142.3V448z\"></path></svg>					</a>\n							<h3>Navigacija</h3>							<ul>\n							<li>\n											<a href=\"http://pocetna\">\n											Početna\n											</a>\n									</li>\n								<li>\n											<a href=\"/o-nama\">\n											O nama\n											</a>\n									</li>\n								<li>\n											<a href=\"/usluge\">\n											Usluge\n											</a>\n									</li>\n								<li>\n											<a href=\"/galerija\">\n											Galerija\n											</a>\n									</li>\n								<li>\n											<a href=\"/kontakt\">\n											Kontakt\n											</a>\n									</li>\n						</ul>\n							<h3>Kontakt</h3>							<ul>\n							<li>\n											<a href=\"#\">\n											+381 64 123 4567\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											info@mihalaser.rs\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Industrijska zona bb, 11000 Beograd, Srbija\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Pon - Pet: 08:00 - 17:00 | Sub: 08:00 - 14:00\n											</a>\n									</li>\n						</ul>\n							<p>© 2026 Miha Laser — Laserske usluge. Sva prava zadržana.</p>','Pocetna','','inherit','closed','closed','','7-revision-v1','','','2026-11-04 13:20:20','2026-11-04 13:20:20','',7,'http://mihamiha.local/?p=193',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (194,1,'2026-11-04 13:20:20','2026-11-04 13:20:20','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n									<!DOCTYPE html>\n<html lang=\"sr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Services Ticker Bar</title>\n  <!-- Uvoz Outfit fonta sa Google Fonts -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n    }\n    body {\n      font-family: \'Outfit\', sans-serif;\n    }\n    /* Glavni kontejner trake */\n    .ticker-bar {\n      width: 100%;\n      height: 54px;\n      background-color: #0d111a;\n      border-top: 1px solid rgba(255, 255, 255, 0.1);\n      border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n      display: flex;\n      align-items: center;\n      overflow: hidden;\n      white-space: nowrap;\n      position: relative;\n    }\n    /* Sadržaj trake koji se ponavlja/scroll-uje */\n    .ticker-track {\n      display: flex;\n      align-items: center;\n      gap: 24px;\n      padding: 0 16px;\n      width: max-content;\n    }\n    /* Pojedinačna stavka */\n    .ticker-item {\n      display: inline-flex;\n      align-items: center;\n      gap: 24px;\n      font-size: 13px;\n      font-weight: 700;\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      color: #94a3b8;\n      transition: color 0.3s ease;\n      cursor: pointer;\n    }\n    .ticker-item:hover {\n      color: #00e5ff;\n    }\n    /* Romboidni separator (ikonica iz dizajna) */\n    .ticker-separator {\n      width: 8px;\n      height: 8px;\n      background-color: #00e5ff;\n      transform: rotate(45deg);\n      display: inline-block;\n      box-shadow: 0 0 8px rgba(0, 229, 255, 0.6);\n    }\n    /* Responzivna animacija za mobilne i manje ekrane */\n    @media (max-width: 1200px) {\n      .ticker-track {\n        animation: scrollTicker 25s linear infinite;\n      }\n      .ticker-bar:hover .ticker-track {\n        animation-play-state: paused; /* Pauzira na hover */\n      }\n    }\n    @keyframes scrollTicker {\n      0% {\n        transform: translateX(0);\n      }\n      100% {\n        transform: translateX(-50%);\n      }\n    }\n  </style>\n</head>\n<body>\n      <!-- Prvi set stavki -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n      <!-- Duplirani set stavki za beskonačni (infinite) loop na manjim ekranima -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n</body>\n</html>					<p data-interaction-id=\"ad1294f\">// USLUGE</p>\n					<h2 data-interaction-id=\"bfa24f5\">Kompletna Ponuda Laserskih i CNC<br>Usluga</h2>\n										<a href=\"/usluge\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Sve usluge\n					</a>\n																			<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge.png\" alt=\"\" />																<p data-interaction-id=\"c96585c\">Fiber Laser 6kW</p>\n					<h2 data-interaction-id=\"800d1ef\">Lasersko Sečenje Metala</h2>\n					<p data-interaction-id=\"1117b55\">Visokoefikasno fiber sečenje crnog lima,<br>inoksa, aluminijuma i mesinga čistih ivica bez<br>potrebe za dodatnom obradom. Idealno za…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge2.png\" alt=\"\" />																<p data-interaction-id=\"f777c5e\">CO2 &amp; Fiber Marker</p>\n					<h2 data-interaction-id=\"db15816\">Lasersko Graviranje</h2>\n					<p data-interaction-id=\"d80653a\">Precizno graviranje logotipa, natpisa, tekstura<br>i serijskih oznaka na drvetu, pleksiglasu, akrilu,<br>koži i metalu. Od reklamne galanterije do…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge3.png\" alt=\"\" />																<p data-interaction-id=\"77dde52\">Fiber Marker</p>\n					<h2 data-interaction-id=\"55fce89\">Industrijsko Obeležavanje</h2>\n					<p data-interaction-id=\"51f3466\">Trajno obeležavanje mašinskih delova, alata,<br>industrijskih tablica, QR kodova i serijskih<br>brojeva na metalu. Obeležja otporna na…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge4.png\" alt=\"\" />																<p data-interaction-id=\"1c0065f\">CNC Glodalica &amp; Apkan</p>\n					<h2 data-interaction-id=\"9ee5c28\">CNC Obrada &amp; Savijanje</h2>\n					<p data-interaction-id=\"7f1b60c\">Dodatna obrada, CNC glodanje, savijanje na<br>apkan presi i izrada kompletnih sklopova po<br>vašem nacrtu. Kompletna završna obrada do</p>\n					<p data-interaction-id=\"f74c5c5\">// KAKO RADIMO</p>\n					<h2 data-interaction-id=\"c07ecac\">4 Koraka od Crteža do Gotovog Proizvoda</h2>\n					01\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"4b7e3d9\">Slanje upita i CAD fajla</h2>\n					<p data-interaction-id=\"2770fad\">Pošaljite crtež u DXF, DWG ili PDF<br>formatu sa željenim debljinama i<br>količinom.</p>\n					02\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"5d9f438\">Analiza i Ponuda</h2>\n					<p data-interaction-id=\"f76d4f9\">Optimizujemo kretanje lasera i šaljemo najpovoljniju ponudu u roku od par sati.</p>\n					03\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"c66a3e4\">Laserska Obrada</h2>\n					<p data-interaction-id=\"4b56d36\">Sečenje i graviranje na visokopreciznim CNC fiber mašinama uz stalni nadzor.</p>\n					04\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"f5f3e1b\">Kontrola i Isporuka</h2>\n					<p data-interaction-id=\"3b92bdf\">Svaki komad prolazi proveru dimenzija pre pakovanja i slanja ili preuzimanja.</p>\n					<img data-interaction-id=\"37875af\" id=\"70\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png\" width=\"616\" height=\"444\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png 616w, http://mihamiha.local/wp-content/uploads/2026/11/onama-300x216.png 300w\" alt=\"\"/>					<p data-interaction-id=\"edda545\">// ZAŠTO MI</p>\n					<h3 data-interaction-id=\"c612355\">Spoj Tehnologije, Iskustva i Strasti prema Metalu</h3>\n					<p data-interaction-id=\"8af860f\">Miha Laser je pouzdan partner za industrijska preduzeća, arhitekte, dizajnere i pojedince. Nudimo kompletnu uslugu sečenja i graviranja uz podršku za tehničku<br>pripremu fajlova.</p>\n							<ul>\n							<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Fiber laser najnovije generacije za metale do 20mm debljine\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										CO2 laser za besprekorno graviranje drveta, pleksiglasa i kože\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Kontrola kvaliteta svakog komada pre isporuke\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Pomoć pri izradi CAD modela i optimizaciji utroška materijala\n									</li>\n						</ul>\n												<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Više o nama\n					</a>\n						<p>Imate crtez? Mi imamo laser</p>			<p data-interaction-id=\"d3dd46d\">Pošaljite nam DXF, DWG ili PDF fajl i dobijte ponudu u roku od par sati.</p>\n										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Zatražite Ponudu\n					</a>\n									<img data-interaction-id=\"492b45b\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"#\">\n						X-twitter\n						<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M389.2 48h70.6L305.6 224.2 487 464H345L233.7 318.6 106.5 464H35.8L200.7 275.5 26.8 48H172.4L272.9 180.9 389.2 48zM364.4 421.8h39.1L151.1 88h-42L364.4 421.8z\"></path></svg>					</a>\n					<a href=\"#\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>					</a>\n					<a href=\"#\">\n						Linkedin-in\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M100.28 448H7.4V148.9h92.88zM53.79 108.1C24.09 108.1 0 83.5 0 53.8a53.79 53.79 0 0 1 107.58 0c0 29.7-24.1 54.3-53.79 54.3zM447.9 448h-92.68V302.4c0-34.7-.7-79.2-48.29-79.2-48.29 0-55.69 37.7-55.69 76.7V448h-92.78V148.9h89.08v40.8h1.3c12.4-23.5 42.69-48.3 87.88-48.3 94 0 111.28 61.9 111.28 142.3V448z\"></path></svg>					</a>\n							<h3>Navigacija</h3>							<ul>\n							<li>\n											<a href=\"http://pocetna\">\n											Početna\n											</a>\n									</li>\n								<li>\n											<a href=\"/o-nama\">\n											O nama\n											</a>\n									</li>\n								<li>\n											<a href=\"/usluge\">\n											Usluge\n											</a>\n									</li>\n								<li>\n											<a href=\"/galerija\">\n											Galerija\n											</a>\n									</li>\n								<li>\n											<a href=\"/kontakt\">\n											Kontakt\n											</a>\n									</li>\n						</ul>\n							<h3>Kontakt</h3>							<ul>\n							<li>\n											<a href=\"#\">\n											+381 64 123 4567\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											info@mihalaser.rs\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Industrijska zona bb, 11000 Beograd, Srbija\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Pon - Pet: 08:00 - 17:00 | Sub: 08:00 - 14:00\n											</a>\n									</li>\n						</ul>\n							<p>© 2026 Miha Laser — Laserske usluge. Sva prava zadržana.</p>','Pocetna','','inherit','closed','closed','','7-revision-v1','','','2026-11-04 13:20:20','2026-11-04 13:20:20','',7,'http://mihamiha.local/?p=194',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (195,1,'2026-11-04 13:20:21','2026-11-04 13:20:21','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-4f7b22a .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n									<!DOCTYPE html>\n<html lang=\"sr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Services Ticker Bar</title>\n  <!-- Uvoz Outfit fonta sa Google Fonts -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n    }\n    body {\n      font-family: \'Outfit\', sans-serif;\n    }\n    /* Glavni kontejner trake */\n    .ticker-bar {\n      width: 100%;\n      height: 54px;\n      background-color: #0d111a;\n      border-top: 1px solid rgba(255, 255, 255, 0.1);\n      border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n      display: flex;\n      align-items: center;\n      overflow: hidden;\n      white-space: nowrap;\n      position: relative;\n    }\n    /* Sadržaj trake koji se ponavlja/scroll-uje */\n    .ticker-track {\n      display: flex;\n      align-items: center;\n      gap: 24px;\n      padding: 0 16px;\n      width: max-content;\n    }\n    /* Pojedinačna stavka */\n    .ticker-item {\n      display: inline-flex;\n      align-items: center;\n      gap: 24px;\n      font-size: 13px;\n      font-weight: 700;\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      color: #94a3b8;\n      transition: color 0.3s ease;\n      cursor: pointer;\n    }\n    .ticker-item:hover {\n      color: #00e5ff;\n    }\n    /* Romboidni separator (ikonica iz dizajna) */\n    .ticker-separator {\n      width: 8px;\n      height: 8px;\n      background-color: #00e5ff;\n      transform: rotate(45deg);\n      display: inline-block;\n      box-shadow: 0 0 8px rgba(0, 229, 255, 0.6);\n    }\n    /* Responzivna animacija za mobilne i manje ekrane */\n    @media (max-width: 1200px) {\n      .ticker-track {\n        animation: scrollTicker 25s linear infinite;\n      }\n      .ticker-bar:hover .ticker-track {\n        animation-play-state: paused; /* Pauzira na hover */\n      }\n    }\n    @keyframes scrollTicker {\n      0% {\n        transform: translateX(0);\n      }\n      100% {\n        transform: translateX(-50%);\n      }\n    }\n  </style>\n</head>\n<body>\n      <!-- Prvi set stavki -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n      <!-- Duplirani set stavki za beskonačni (infinite) loop na manjim ekranima -->\n      Lasersko Sečenje \n      Lasersko Graviranje \n      Fiber Laser 6KW \n      CO2 Graviranje \n      Industrijsko Obeležavanje \n      CNC Obrada \n      Savijanje Lima \n</body>\n</html>					<p data-interaction-id=\"ad1294f\">// USLUGE</p>\n					<h2 data-interaction-id=\"bfa24f5\">Kompletna Ponuda Laserskih i CNC<br>Usluga</h2>\n										<a href=\"/usluge\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Sve usluge\n					</a>\n																			<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge.png\" alt=\"\" />																<p data-interaction-id=\"c96585c\">Fiber Laser 6kW</p>\n					<h2 data-interaction-id=\"800d1ef\">Lasersko Sečenje Metala</h2>\n					<p data-interaction-id=\"1117b55\">Visokoefikasno fiber sečenje crnog lima,<br>inoksa, aluminijuma i mesinga čistih ivica bez<br>potrebe za dodatnom obradom. Idealno za…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge2.png\" alt=\"\" />																<p data-interaction-id=\"f777c5e\">CO2 &amp; Fiber Marker</p>\n					<h2 data-interaction-id=\"db15816\">Lasersko Graviranje</h2>\n					<p data-interaction-id=\"d80653a\">Precizno graviranje logotipa, natpisa, tekstura<br>i serijskih oznaka na drvetu, pleksiglasu, akrilu,<br>koži i metalu. Od reklamne galanterije do…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge3.png\" alt=\"\" />																<p data-interaction-id=\"77dde52\">Fiber Marker</p>\n					<h2 data-interaction-id=\"55fce89\">Industrijsko Obeležavanje</h2>\n					<p data-interaction-id=\"51f3466\">Trajno obeležavanje mašinskih delova, alata,<br>industrijskih tablica, QR kodova i serijskih<br>brojeva na metalu. Obeležja otporna na…</p>\n															<img width=\"288\" height=\"176\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/usluge4.png\" alt=\"\" />																<p data-interaction-id=\"1c0065f\">CNC Glodalica &amp; Apkan</p>\n					<h2 data-interaction-id=\"9ee5c28\">CNC Obrada &amp; Savijanje</h2>\n					<p data-interaction-id=\"7f1b60c\">Dodatna obrada, CNC glodanje, savijanje na<br>apkan presi i izrada kompletnih sklopova po<br>vašem nacrtu. Kompletna završna obrada do</p>\n					<p data-interaction-id=\"f74c5c5\">// KAKO RADIMO</p>\n					<h2 data-interaction-id=\"c07ecac\">4 Koraka od Crteža do Gotovog Proizvoda</h2>\n					01\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"4b7e3d9\">Slanje upita i CAD fajla</h2>\n					<p data-interaction-id=\"2770fad\">Pošaljite crtež u DXF, DWG ili PDF<br>formatu sa željenim debljinama i<br>količinom.</p>\n					02\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"5d9f438\">Analiza i Ponuda</h2>\n					<p data-interaction-id=\"f76d4f9\">Optimizujemo kretanje lasera i šaljemo najpovoljniju ponudu u roku od par sati.</p>\n					03\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"c66a3e4\">Laserska Obrada</h2>\n					<p data-interaction-id=\"4b56d36\">Sečenje i graviranje na visokopreciznim CNC fiber mašinama uz stalni nadzor.</p>\n					04\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"f5f3e1b\">Kontrola i Isporuka</h2>\n					<p data-interaction-id=\"3b92bdf\">Svaki komad prolazi proveru dimenzija pre pakovanja i slanja ili preuzimanja.</p>\n					<img data-interaction-id=\"37875af\" id=\"70\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png\" width=\"616\" height=\"444\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/onama.png 616w, http://mihamiha.local/wp-content/uploads/2026/11/onama-300x216.png 300w\" alt=\"\"/>					<p data-interaction-id=\"edda545\">// ZAŠTO MI</p>\n					<h3 data-interaction-id=\"c612355\">Spoj Tehnologije, Iskustva i Strasti prema Metalu</h3>\n					<p data-interaction-id=\"8af860f\">Miha Laser je pouzdan partner za industrijska preduzeća, arhitekte, dizajnere i pojedince. Nudimo kompletnu uslugu sečenja i graviranja uz podršku za tehničku<br>pripremu fajlova.</p>\n							<ul>\n							<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Fiber laser najnovije generacije za metale do 20mm debljine\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										CO2 laser za besprekorno graviranje drveta, pleksiglasa i kože\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Kontrola kvaliteta svakog komada pre isporuke\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm0 48c110.532 0 200 89.451 200 200 0 110.532-89.451 200-200 200-110.532 0-200-89.451-200-200 0-110.532 89.451-200 200-200m140.204 130.267l-22.536-22.718c-4.667-4.705-12.265-4.736-16.97-.068L215.346 303.697l-59.792-60.277c-4.667-4.705-12.265-4.736-16.97-.069l-22.719 22.536c-4.705 4.667-4.736 12.265-.068 16.971l90.781 91.516c4.667 4.705 12.265 4.736 16.97.068l172.589-171.204c4.704-4.668 4.734-12.266.067-16.971z\"></path></svg>						\n										Pomoć pri izradi CAD modela i optimizaciji utroška materijala\n									</li>\n						</ul>\n												<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Više o nama\n					</a>\n						<p>Imate crtez? Mi imamo laser</p>			<p data-interaction-id=\"d3dd46d\">Pošaljite nam DXF, DWG ili PDF fajl i dobijte ponudu u roku od par sati.</p>\n										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									Zatražite Ponudu\n					</a>\n									<img data-interaction-id=\"492b45b\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"#\">\n						X-twitter\n						<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M389.2 48h70.6L305.6 224.2 487 464H345L233.7 318.6 106.5 464H35.8L200.7 275.5 26.8 48H172.4L272.9 180.9 389.2 48zM364.4 421.8h39.1L151.1 88h-42L364.4 421.8z\"></path></svg>					</a>\n					<a href=\"#\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>					</a>\n					<a href=\"#\">\n						Linkedin-in\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M100.28 448H7.4V148.9h92.88zM53.79 108.1C24.09 108.1 0 83.5 0 53.8a53.79 53.79 0 0 1 107.58 0c0 29.7-24.1 54.3-53.79 54.3zM447.9 448h-92.68V302.4c0-34.7-.7-79.2-48.29-79.2-48.29 0-55.69 37.7-55.69 76.7V448h-92.78V148.9h89.08v40.8h1.3c12.4-23.5 42.69-48.3 87.88-48.3 94 0 111.28 61.9 111.28 142.3V448z\"></path></svg>					</a>\n							<h3>Navigacija</h3>							<ul>\n							<li>\n											<a href=\"http://pocetna\">\n											Početna\n											</a>\n									</li>\n								<li>\n											<a href=\"/o-nama\">\n											O nama\n											</a>\n									</li>\n								<li>\n											<a href=\"/usluge\">\n											Usluge\n											</a>\n									</li>\n								<li>\n											<a href=\"/galerija\">\n											Galerija\n											</a>\n									</li>\n								<li>\n											<a href=\"/kontakt\">\n											Kontakt\n											</a>\n									</li>\n						</ul>\n							<h3>Kontakt</h3>							<ul>\n							<li>\n											<a href=\"#\">\n											+381 64 123 4567\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											info@mihalaser.rs\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Industrijska zona bb, 11000 Beograd, Srbija\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Pon - Pet: 08:00 - 17:00 | Sub: 08:00 - 14:00\n											</a>\n									</li>\n						</ul>\n							<p>© 2026 Miha Laser — Laserske usluge. Sva prava zadržana.</p>','Pocetna','','inherit','closed','closed','','7-revision-v1','','','2026-11-04 13:20:21','2026-11-04 13:20:21','',7,'http://mihamiha.local/?p=195',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (196,1,'2026-11-04 13:21:45','2026-11-04 13:21:45','{\n    \"custom_css[hello-elementor]\": {\n        \"value\": \"/* Uvoz Outfit fonta sa Google Fonts */\\n@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&display=swap\');\\n\\n/* Osnovni font za ceo sajt (Body, Paragraphs, Spans) */\\nbody, p, span, li, a {\\n  font-family: \'Outfit\', sans-serif !important;\\n  font-size: 16px;\\n  line-height: 24px;\\n  font-weight: 400;\\n}\\n/* Osnovno stanje - prozirna ili neutralna ivica */\\n.step-box {\\n  border: 1px solid rgba(255, 255, 255, 0.08) !important;\\n  transition: border-color 0.3s ease, transform 0.3s ease;\\n}\\n/* Osnovno stanje kartice */\\n.elementor-element-3f1a111 {\\n  background-color: #121824 !important; /* Tamna pozadina kartice */\\n  border: 1px solid rgba(255, 255, 255, 0.08) !important; /* Suptilna siva ivica */\\n  border-radius: 8px !important;\\n  transition: all 0.3s ease-in-out !important;\\n  overflow: hidden;\\n}\\n\\n/* Hover efekat - Cyan/Tirkizna ivica i blagi podizaj kartice */\\n.elementor-element-3f1a111:hover {\\n  border-color: #00e5ff !important; /* Cyan ivica iz Figme */\\n  box-shadow: 0 8px 24px rgba(0, 229, 255, 0.15) !important; /* Blagi neonski sjaj oko kartice */\\n  transform: translateY(-4px) !important; /* Blago podizanje kartice pri prela\\u017eenju mi\\u0161em */\\n}\\n/* Hover stanje - cyan tirkizna ivica kao u dizajnu */\\n.step-box:hover {\\n  border-color: #00e5ff !important;\\n}\\n/* Pode\\u0161avanje za H2 naslove */\\nh2 {\\n  font-family: \'Outfit\', sans-serif !important;\\n  font-size: 36px;\\n  line-height: 40px;\\n  font-weight: 800;\\n  letter-spacing: -0.9px;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-11-04 13:21:45\"\n    }\n}','','','trash','closed','closed','','b716de72-cf49-4964-bd8d-be7448a1f98c','','','2026-11-04 13:21:45','2026-11-04 13:21:45','',0,'http://mihamiha.local/b716de72-cf49-4964-bd8d-be7448a1f98c/',0,'customize_changeset','',0);
