INSERT INTO `wp_posts` VALUES (245,1,'2026-11-04 16:16:11','2026-11-04 16:16:11','{\n    \"custom_css[hello-elementor]\": {\n        \"value\": \"/* Uvoz Outfit fonta sa Google Fonts */\\n@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&display=swap\');\\n\\n/* Osnovni font za ceo sajt (Body, Paragraphs, Spans) */\\nbody, p, span, li, a {\\n  font-family: \'Outfit\', sans-serif !important;\\n  font-size: 16px;\\n  line-height: 24px;\\n  font-weight: 400;\\n}\\n\\n/* Primorava kontejner slike i samu sliku da idu od ivice do ivice */\\n.elementor-element-3f1a111 {\\n  padding: 0 !important; /* Bri\\u0161e padding cele kartice ako ga dr\\u017ei zarobljenog */\\n}\\n\\n.elementor-element-3f1a111 .elementor-widget-image {\\n  margin-left: 0 !important;\\n  margin-right: 0 !important;\\n  padding: 0 !important;\\n  width: 100% !important;\\n}\\n.site-header,\\n.dynamic-header,\\n.menu-dropdown-tablet,\\n.site-footer,\\n.dynamic-footer,\\n.footer-has-copyright {\\n  display: none !important;\\n}\\n.elementor-element-3f1a111 .elementor-widget-image img {\\n  width: 100% !important;\\n  max-width: 100% !important;\\n  height: 180px !important; /* Podesi visinu slike po \\u017eelji */\\n  object-fit: cover !important;\\n  border-top-left-radius: 8px;  /* Prati zaobljenje kartice */\\n  border-top-right-radius: 8px; /* Prati zaobljenje kartice */\\n  display: block !important;\\n}\\n/* Osnovno stanje - prozirna ili neutralna ivica */\\n.step-box {\\n  border: 1px solid rgba(255, 255, 255, 0.08) !important;\\n  transition: border-color 0.3s ease, transform 0.3s ease;\\n}\\n/* Osnovno stanje kartice */\\n.elementor-element-3f1a111 {\\n  background-color: #121824 !important; /* Tamna pozadina kartice */\\n  border: 1px solid rgba(255, 255, 255, 0.08) !important; /* Suptilna siva ivica */\\n  border-radius: 8px !important;\\n  transition: all 0.3s ease-in-out !important;\\n  overflow: hidden;\\n}\\n/* Postavlja sliku da ide od ivice do ivice kartice i popuni \\u0161irinu */\\n.elementor-element-3f1a111 .elementor-widget-image img {\\n  width: 100% !important;\\n  max-width: 100% !important;\\n  height: 180px !important; /* Prilagodi visinu po \\u017eelji (npr. 160px - 200px) */\\n  object-fit: cover !important;\\n  border-top-left-radius: 8px;  /* Prati zaobljenje same kartice */\\n  border-top-right-radius: 8px; /* Prati zaobljenje same kartice */\\n  display: block;\\n}\\n\\n/* Ako ima nekog unutra\\u0161njeg paddinga u kontejneru slike, bri\\u0161emo ga da udari u ivice */\\n.elementor-element-3f1a111 .elementor-widget-image {\\n  padding: 0 !important;\\n}\\n/* Hover efekat - Cyan/Tirkizna ivica i blagi podizaj kartice */\\n.elementor-element-3f1a111:hover {\\n  border-color: #00e5ff !important; /* Cyan ivica iz Figme */\\n  box-shadow: 0 8px 24px rgba(0, 229, 255, 0.15) !important; /* Blagi neonski sjaj oko kartice */\\n  transform: translateY(-4px) !important; /* Blago podizanje kartice pri prela\\u017eenju mi\\u0161em */\\n}\\n/* Hover stanje - cyan tirkizna ivica kao u dizajnu */\\n.step-box:hover {\\n  border-color: #00e5ff !important;\\n}\\n/* Pode\\u0161avanje za H2 naslove */\\nh2 {\\n  font-family: \'Outfit\', sans-serif !important;\\n  font-size: 36px;\\n  line-height: 40px;\\n  font-weight: 800;\\n  letter-spacing: -0.9px;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-11-04 16:16:11\"\n    }\n}','','','trash','closed','closed','','04c758a9-6661-4f77-b6e4-b2f36b1160da','','','2026-11-04 16:16:11','2026-11-04 16:16:11','',0,'http://mihamiha.local/04c758a9-6661-4f77-b6e4-b2f36b1160da/',0,'customize_changeset','',0);
INSERT INTO `wp_posts` VALUES (246,1,'2026-11-04 16:16:11','2026-11-04 16:16:11','/* Uvoz Outfit fonta sa Google Fonts */\n@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&display=swap\');\n\n/* Osnovni font za ceo sajt (Body, Paragraphs, Spans) */\nbody, p, span, li, a {\n  font-family: \'Outfit\', sans-serif !important;\n  font-size: 16px;\n  line-height: 24px;\n  font-weight: 400;\n}\n\n/* Primorava kontejner slike i samu sliku da idu od ivice do ivice */\n.elementor-element-3f1a111 {\n  padding: 0 !important; /* Briše padding cele kartice ako ga drži zarobljenog */\n}\n\n.elementor-element-3f1a111 .elementor-widget-image {\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n  padding: 0 !important;\n  width: 100% !important;\n}\n.site-header,\n.dynamic-header,\n.menu-dropdown-tablet,\n.site-footer,\n.dynamic-footer,\n.footer-has-copyright {\n  display: none !important;\n}\n.elementor-element-3f1a111 .elementor-widget-image img {\n  width: 100% !important;\n  max-width: 100% !important;\n  height: 180px !important; /* Podesi visinu slike po želji */\n  object-fit: cover !important;\n  border-top-left-radius: 8px;  /* Prati zaobljenje kartice */\n  border-top-right-radius: 8px; /* Prati zaobljenje kartice */\n  display: block !important;\n}\n/* Osnovno stanje - prozirna ili neutralna ivica */\n.step-box {\n  border: 1px solid rgba(255, 255, 255, 0.08) !important;\n  transition: border-color 0.3s ease, transform 0.3s ease;\n}\n/* Osnovno stanje kartice */\n.elementor-element-3f1a111 {\n  background-color: #121824 !important; /* Tamna pozadina kartice */\n  border: 1px solid rgba(255, 255, 255, 0.08) !important; /* Suptilna siva ivica */\n  border-radius: 8px !important;\n  transition: all 0.3s ease-in-out !important;\n  overflow: hidden;\n}\n/* Postavlja sliku da ide od ivice do ivice kartice i popuni širinu */\n.elementor-element-3f1a111 .elementor-widget-image img {\n  width: 100% !important;\n  max-width: 100% !important;\n  height: 180px !important; /* Prilagodi visinu po želji (npr. 160px - 200px) */\n  object-fit: cover !important;\n  border-top-left-radius: 8px;  /* Prati zaobljenje same kartice */\n  border-top-right-radius: 8px; /* Prati zaobljenje same kartice */\n  display: block;\n}\n\n/* Ako ima nekog unutrašnjeg paddinga u kontejneru slike, brišemo ga da udari u ivice */\n.elementor-element-3f1a111 .elementor-widget-image {\n  padding: 0 !important;\n}\n/* Hover efekat - Cyan/Tirkizna ivica i blagi podizaj kartice */\n.elementor-element-3f1a111:hover {\n  border-color: #00e5ff !important; /* Cyan ivica iz Figme */\n  box-shadow: 0 8px 24px rgba(0, 229, 255, 0.15) !important; /* Blagi neonski sjaj oko kartice */\n  transform: translateY(-4px) !important; /* Blago podizanje kartice pri prelaženju mišem */\n}\n/* Hover stanje - cyan tirkizna ivica kao u dizajnu */\n.step-box:hover {\n  border-color: #00e5ff !important;\n}\n/* Podešavanje za H2 naslove */\nh2 {\n  font-family: \'Outfit\', sans-serif !important;\n  font-size: 36px;\n  line-height: 40px;\n  font-weight: 800;\n  letter-spacing: -0.9px;\n}','hello-elementor','','inherit','closed','closed','','41-revision-v1','','','2026-11-04 16:16:11','2026-11-04 16:16:11','',41,'http://mihamiha.local/?p=246',0,'revision','',0);
