ccept the terms and conditions before sending your message.\nPlease fill out this field.\nThis field has a too long input.\nThis field has a too short input.\nThere was an unknown error uploading the file.\nYou are not allowed to upload files of this type.\nThe uploaded file is too large.\nThere was an error uploading the file.\nPlease enter a date in YYYY-MM-DD format.\nThis field has a too early date.\nThis field has a too late date.\nPlease enter a number.\nThis field has a too small number.\nThis field has a too large number.\nThe answer to the quiz is incorrect.\nPlease enter an email address.\nPlease enter a URL.\nPlease enter a telephone number.','kontaktforma','','publish','closed','closed','','kontaktforma','','','2026-11-04 16:18:43','2026-11-04 16:18:43','',0,'http://mihamiha.local/?post_type=wpcf7_contact_form&#038;p=248',0,'wpcf7_contact_form','',0);
INSERT INTO `wp_posts` VALUES (249,1,'2026-11-04 16:19:19','2026-11-04 16:19:19','{\n    \"custom_css[hello-elementor]\": {\n        \"value\": \"/* Uvoz Outfit fonta sa Google Fonts */\\n@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&display=swap\');\\n\\n/* Osnovni font za ceo sajt (Body, Paragraphs, Spans) */\\nbody, p, span, li, a {\\n  font-family: \'Outfit\', sans-serif !important;\\n  font-size: 16px;\\n  line-height: 24px;\\n  font-weight: 400;\\n}\\n@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;700;800&display=swap\');\\n\\n.inquiry-form {\\n  background-color: #111823;\\n  border: 1px solid rgba(255, 255, 255, 0.08);\\n  padding: 40px;\\n  max-width: 800px;\\n  width: 100%;\\n  box-sizing: border-box;\\n  font-family: \'Outfit\', sans-serif;\\n  display: flex;\\n  flex-direction: column;\\n  gap: 20px;\\n}\\n\\n.form-tag {\\n  display: flex;\\n  align-items: center;\\n  gap: 10px;\\n  color: #00e5ff;\\n  font-size: 13px;\\n  font-weight: 700;\\n  letter-spacing: 2px;\\n  margin-bottom: 10px;\\n}\\n\\n.form-row {\\n  display: grid;\\n  grid-template-columns: 1fr 1fr;\\n  gap: 20px;\\n}\\n\\n.input-group {\\n  position: relative;\\n  width: 100%;\\n}\\n\\n.inquiry-form input,\\n.inquiry-form select,\\n.inquiry-form textarea {\\n  width: 100%;\\n  background-color: #0b0f17;\\n  border: 1px solid rgba(255, 255, 255, 0.12);\\n  padding: 16px 20px;\\n  color: #ffffff;\\n  font-family: \'Outfit\', sans-serif;\\n  font-size: 14px;\\n  outline: none;\\n  box-sizing: border-box;\\n  transition: border-color 0.2s ease, box-shadow 0.2s ease;\\n}\\n\\n.inquiry-form input::placeholder,\\n.inquiry-form textarea::placeholder {\\n  color: #64748b;\\n}\\n\\n.inquiry-form select {\\n  appearance: none;\\n  background-image: url(\\\"data:image/svg+xml;utf8,<svg xmlns=\'http://www.w3.org/2000/svg\' width=\'16\' height=\'16\' viewBox=\'0 0 24 24\' fill=\'none\' stroke=\'%2364748b\' stroke-width=\'2\' stroke-linecap=\'round\' stroke-linejoin=\'round\'><polyline points=\'6 9 12 15 18 9\'></polyline></svg>\\\");\\n  background-repeat: no-repeat;\\n  background-position: right 20px center;\\n  cursor: pointer;\\n}\\n\\n.inquiry-form select option {\\n  background-color: #0b0f17;\\n  color: #ffffff;\\n}\\n\\n.inquiry-form textarea {\\n  resize: vertical;\\n  min-height: 140px;\\n}\\n\\n.inquiry-form input:focus,\\n.inquiry-form select:focus,\\n.inquiry-form textarea:focus {\\n  border-color: #00e5ff;\\n  box-shadow: 0 0 8px rgba(0, 229, 255, 0.2);\\n}\\n\\n.submit-btn {\\n  background-color: #00e5ff;\\n  color: #0b0f17;\\n  border: none;\\n  padding: 16px 32px;\\n  font-family: \'Outfit\', sans-serif;\\n  font-size: 15px;\\n  font-weight: 800;\\n  letter-spacing: 1px;\\n  cursor: pointer;\\n  display: inline-flex;\\n  align-items: center;\\n  justify-content: center;\\n  gap: 10px;\\n  align-self: flex-start;\\n  transition: background-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;\\n}\\n\\n.submit-btn:hover {\\n  background-color: #33ebff;\\n  box-shadow: 0 0 16px rgba(0, 229, 255, 0.4);\\n  transform: translateY(-1px);\\n}\\n\\n@media (max-width: 640px) {\\n  .form-row {\\n    grid-template-columns: 1fr;\\n  }\\n  \\n  .submit-btn {\\n    width: 100%;\\n  }\\n  \\n  .inquiry-form {\\n    padding: 24px;\\n  }\\n}\\n/* Primorava kontejner slike i samu sliku da idu od ivice do ivice */\\n.elementor-element-3f1a111 {\\n  padding: 0 !important; /* Bri\\u0161e padding cele kartice ako ga dr\\u017ei zarobljenog */\\n}\\n\\n.elementor-element-3f1a111 .elementor-widget-image {\\n  margin-left: 0 !important;\\n  margin-right: 0 !important;\\n  padding: 0 !important;\\n  width: 100% !important;\\n}\\n.site-header,\\n.dynamic-header,\\n.menu-dropdown-tablet,\\n.site-footer,\\n.dynamic-footer,\\n.footer-has-copyright {\\n  display: none !important;\\n}\\n.elementor-element-3f1a111 .elementor-widget-image img {\\n  width: 100% !important;\\n  max-width: 100% !important;\\n  height: 180px !important; /* Podesi visinu slike po \\u017eelji */\\n  object-fit: cover !important;\\n  border-top-left-radius: 8px;  /* Prati zaobljenje kartice */\\n  border-top-right-radius: 8px; /* Prati zaobljenje kartice */\\n  display: block !important;\\n}\\n/* Osnovno stanje - prozirna ili neutralna ivica */\\n.step-box {\\n  border: 1px solid rgba(255, 255, 255, 0.08) !important;\\n  transition: border-color 0.3s ease, transform 0.3s ease;\\n}\\n/* Osnovno stanje kartice */\\n.elementor-element-3f1a111 {\\n  background-color: #121824 !important; /* Tamna pozadina kartice */\\n  border: 1px solid rgba(255, 255, 255, 0.08) !important; /* Suptilna siva ivica */\\n  border-radius: 8px !important;\\n  transition: all 0.3s ease-in-out !important;\\n  overflow: hidden;\\n}\\n/* Postavlja sliku da ide od ivice do ivice kartice i popuni \\u0161irinu */\\n.elementor-element-3f1a111 .elementor-widget-image img {\\n  width: 100% !important;\\n  max-width: 100% !important;\\n  height: 180px !important; /* Prilagodi visinu po \\u017eelji (npr. 160px - 200px) */\\n  object-fit: cover !important;\\n  border-top-left-radius: 8px;  /* Prati zaobljenje same kartice */\\n  border-top-right-radius: 8px; /* Prati zaobljenje same kartice */\\n  display: block;\\n}\\n\\n/* Ako ima nekog unutra\\u0161njeg paddinga u kontejneru slike, bri\\u0161emo ga da udari u ivice */\\n.elementor-element-3f1a111 .elementor-widget-image {\\n  padding: 0 !important;\\n}\\n/* Hover efekat - Cyan/Tirkizna ivica i blagi podizaj kartice */\\n.elementor-element-3f1a111:hover {\\n  border-color: #00e5ff !important; /* Cyan ivica iz Figme */\\n  box-shadow: 0 8px 24px rgba(0, 229, 255, 0.15) !important; /* Blagi neonski sjaj oko kartice */\\n  transform: translateY(-4px) !important; /* Blago podizanje kartice pri prela\\u017eenju mi\\u0161em */\\n}\\n/* Hover stanje - cyan tirkizna ivica kao u dizajnu */\\n.step-box:hover {\\n  border-color: #00e5ff !important;\\n}\\n/* Pode\\u0161avanje za H2 naslove */\\nh2 {\\n  font-family: \'Outfit\', sans-serif !important;\\n  font-size: 36px;\\n  line-height: 40px;\\n  font-weight: 800;\\n  letter-spacing: -0.9px;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-11-04 16:19:19\"\n    }\n}','','','trash','closed','closed','','5d9e9106-4b56-4cf3-8cd2-b62d22c7bc75','','','2026-11-04 16:19:19','2026-11-04 16:19:19','',0,'http://mihamiha.local/5d9e9106-4b56-4cf3-8cd2-b62d22c7bc75/',0,'customize_changeset','',0);
INSERT INTO `wp_posts` VALUES (250,1,'2026-11-04 16:19:19','2026-11-04 16:19:19','/* Uvoz Outfit fonta sa Google Fonts */\n@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&display=swap\');\n\n/* Osnovni font za ceo sajt (Body, Paragraphs, Spans) */\nbody, p, span, li, a {\n  font-family: \'Outfit\', sans-serif !important;\n  font-size: 16px;\n  line-height: 24px;\n  font-weight: 400;\n}\n@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;700;800&display=swap\');\n\n.inquiry-form {\n  background-color: #111823;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  padding: 40px;\n  max-width: 800px;\n  width: 100%;\n  box-sizing: border-box;\n  font-family: \'Outfit\', sans-serif;\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n.form-tag {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  color: #00e5ff;\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: 2px;\n  margin-bottom: 10px;\n}\n\n.form-row {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 20px;\n}\n\n.input-group {\n  position: relative;\n  width: 100%;\n}\n\n.inquiry-form input,\n.inquiry-form select,\n.inquiry-form textarea {\n  width: 100%;\n  background-color: #0b0f17;\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  padding: 16px 20px;\n  color: #ffffff;\n  font-family: \'Outfit\', sans-serif;\n  font-size: 14px;\n  outline: none;\n  box-sizing: border-box;\n  transition: border-color 0.2s ease, box-shadow 0.2s ease;\n}\n\n.inquiry-form input::placeholder,\n.inquiry-form textarea::placeholder {\n  color: #64748b;\n}\n\n.inquiry-form select {\n  appearance: none;\n  background-image: url(\"data:image/svg+xml;utf8,<svg xmlns=\'http://www.w3.org/2000/svg\' width=\'16\' height=\'16\' viewBox=\'0 0 24 24\' fill=\'none\' stroke=\'%2364748b\' stroke-width=\'2\' stroke-linecap=\'round\' stroke-linejoin=\'round\'><polyline points=\'6 9 12 15 18 9\'></polyline></svg>\");\n  background-repeat: no-repeat;\n  background-position: right 20px center;\n  cursor: pointer;\n}\n\n.inquiry-form select option {\n  background-color: #0b0f17;\n  color: #ffffff;\n}\n\n.inquiry-form textarea {\n  resize: vertical;\n  min-height: 140px;\n}\n\n.inquiry-form input:focus,\n.inquiry-form select:focus,\n.inquiry-form textarea:focus {\n  border-color: #00e5ff;\n  box-shadow: 0 0 8px rgba(0, 229, 255, 0.2);\n}\n\n.submit-btn {\n  background-color: #00e5ff;\n  color: #0b0f17;\n  border: none;\n  padding: 16px 32px;\n  font-family: \'Outfit\', sans-serif;\n  font-size: 15px;\n  font-weight: 800;\n  letter-spacing: 1px;\n  cursor: pointer;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  align-self: flex-start;\n  transition: background-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;\n}\n\n.submit-btn:hover {\n  background-color: #33ebff;\n  box-shadow: 0 0 16px rgba(0, 229, 255, 0.4);\n  transform: translateY(-1px);\n}\n\n@media (max-width: 640px) {\n  .form-row {\n    grid-template-columns: 1fr;\n  }\n  \n  .submit-btn {\n    width: 100%;\n  }\n  \n  .inquiry-form {\n    padding: 24px;\n  }\n}\n/* Primorava kontejner slike i samu sliku da idu od ivice do ivice */\n.elementor-element-3f1a111 {\n  padding: 0 !important; /* Briše padding cele kartice ako ga drži zarobljenog */\n}\n\n.elementor-element-3f1a111 .elementor-widget-image {\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n  padding: 0 !important;\n  width: 100% !important;\n}\n.site-header,\n.dynamic-header,\n.menu-dropdown-tablet,\n.site-footer,\n.dynamic-footer,\n.footer-has-copyright {\n  display: none !important;\n}\n.elementor-element-3f1a111 .elementor-widget-image img {\n  width: 100% !important;\n  max-width: 100% !important;\n  height: 180px !important; /* Podesi visinu slike po želji */\n  object-fit: cover !important;\n  border-top-left-radius: 8px;  /* Prati zaobljenje kartice */\n  border-top-right-radius: 8px; /* Prati zaobljenje kartice */\n  display: block !important;\n}\n/* Osnovno stanje - prozirna ili neutralna ivica */\n.step-box {\n  border: 1px solid rgba(255, 255, 255, 0.08) !important;\n  transition: border-color 0.3s ease, transform 0.3s ease;\n}\n/* Osnovno stanje kartice */\n.elementor-element-3f1a111 {\n  background-color: #121824 !important; /* Tamna pozadina kartice */\n  border: 1px solid rgba(255, 255, 255, 0.08) !important; /* Suptilna siva ivica */\n  border-radius: 8px !important;\n  transition: all 0.3s ease-in-out !important;\n  overflow: hidden;\n}\n/* Postavlja sliku da ide od ivice do ivice kartice i popuni širinu */\n.elementor-element-3f1a111 .elementor-widget-image img {\n  width: 100% !important;\n  max-width: 100% !important;\n  height: 180px !important; /* Prilagodi visinu po želji (npr. 160px - 200px) */\n  object-fit: cover !important;\n  border-top-left-radius: 8px;  /* Prati zaobljenje same kartice */\n  border-top-right-radius: 8px; /* Prati zaobljenje same kartice */\n  display: block;\n}\n\n/* Ako ima nekog unutrašnjeg paddinga u kontejneru slike, brišemo ga da udari u ivice */\n.elementor-element-3f1a111 .elementor-widget-image {\n  padding: 0 !important;\n}\n/* Hover efekat - Cyan/Tirkizna ivica i blagi podizaj kartice */\n.elementor-element-3f1a111:hover {\n  border-color: #00e5ff !important; /* Cyan ivica iz Figme */\n  box-shadow: 0 8px 24px rgba(0, 229, 255, 0.15) !important; /* Blagi neonski sjaj oko kartice */\n  transform: translateY(-4px) !important; /* Blago podizanje kartice pri prelaženju mišem */\n}\n/* Hover stanje - cyan tirkizna ivica kao u dizajnu */\n.step-box:hover {\n  border-color: #00e5ff !important;\n}\n/* Podešavanje za H2 naslove */\nh2 {\n  font-family: \'Outfit\', sans-serif !important;\n  font-size: 36px;\n  line-height: 40px;\n  font-weight: 800;\n  letter-spacing: -0.9px;\n}','hello-elementor','','inherit','closed','closed','','41-revision-v1','','','2026-11-04 16:19:19','2026-11-04 16:19:19','',41,'http://mihamiha.local/?p=250',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (252,1,'2026-11-04 16:27:41','2026-11-04 16:27:41','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-546f9acb .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-546f9acb .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-546f9acb .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-546f9a