INSERT INTO `wp_posts` VALUES (296,1,'2026-11-05 12:17:08','2026-11-05 12:17:08','01\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"2926a627\">Slanje upita i CAD fajla</h2>\n					<p data-interaction-id=\"1a983eb0\">Pošaljite crtež u DXF, DWG ili PDF<br>formatu sa željenim debljinama i<br>količinom.</p>\n					02\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"3315f929\">Analiza i Ponuda</h2>\n					<p data-interaction-id=\"7e0cbb89\">Optimizujemo kretanje lasera i šaljemo najpovoljniju ponudu u roku od par sati.</p>\n					03\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"473e4e18\">Laserska Obrada</h2>\n					<p data-interaction-id=\"48da5f68\">Sečenje i graviranje na visokopreciznim CNC fiber mašinama uz stalni nadzor.</p>\n					04\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@800&display=swap\');\n.number-01 {\n  font-family: \'Outfit\', sans-serif;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  /* Tačna tamno-tirkizna mat boja iz unutrašnjosti broja */\n  color: #0c3b43;\n  /* Suptilna cyan ivica koja stvara urezan/cut-out efekat sa slike */\n  -webkit-text-stroke: 1px rgba(0, 229, 255, 0.25);\n  display: inline-block;\n  letter-spacing: -2px;\n}\n</style>															<img width=\"20\" height=\"20\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/munja.png\" alt=\"\" />																<h2 data-interaction-id=\"6ce5aed3\">Kontrola i Isporuka</h2>\n					<p data-interaction-id=\"26969a16\">Svaki komad prolazi proveru dimenzija pre pakovanja i slanja ili preuzimanja.</p>','imagebox2','','publish','closed','closed','','imagebox2','','','2026-11-05 12:17:09','2026-11-05 12:17:09','',0,'http://mihamiha.local/?elementor_library=imagebox2',0,'elementor_library','',0);
