INSERT INTO `wp_posts` VALUES (306,1,'2026-11-05 12:26:55','2026-11-05 12:26:55','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-70201fc3 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-70201fc3 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-70201fc3 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-70201fc3 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-70201fc3 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-70201fc3 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-70201fc3 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-70201fc3 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n						<p>// O NAMA</p>			<h2 data-interaction-id=\"10f2a92\">Spoj Tehnologije, Iskustva i Strasti prema Metalu</h2>\n		Miha Laser je specijalizovana radionica za visokoprecizno<br/> lasersko sečenje, graviranje i CNC obradu metala i nemetala.<p>// NAŠA PRIČA</p>			<h2 data-interaction-id=\"0f5d02f\">Od Male Radionice do Pouzdanog Industrijskog Partnera</h2>\n		<p>Miha Laser je nastao iz strasti prema preciznoj obradi metala. Ono što je počelo kao mala zanatska radionica, danas je savremen laserski centar opremljen fiber i CO2 tehnologijom najnovije generacije.</p><p>Sarađujemo sa industrijskim preduzećima, arhitektama, dizajnerima i pojedincima. Bilo da vam treba jedan unikatni komad ili serija od hiljadu komada — svaki posao prolazi isti strogi proces kontrole kvaliteta.</p>													<img width=\"576\" height=\"400\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Radionica.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Radionica.png 576w, http://mihamiha.local/wp-content/uploads/2026/11/Radionica-300x208.png 300w\" sizes=\"(max-width: 576px) 100vw, 576px\" />																<p data-interaction-id=\"38bf60f7\">// VREDNOSTI</p>\n					<h2 data-interaction-id=\"3c44037f\">Na Čemu Baziramo Svaki Posao</h2>\n															<img width=\"28\" height=\"28\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/SVG.png\" alt=\"\" />																<h2 data-interaction-id=\"463357de\">Preciznost</h2>\n					<p data-interaction-id=\"64307cec\">Tolerancije do 0.01 mm na svakom<br>komadu, bez kompromisa.</p>\n															<img width=\"28\" height=\"28\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/brzina.png\" alt=\"\" />																<h2 data-interaction-id=\"1985011b\">Brzina</h2>\n					<p data-interaction-id=\"45638f99\">Uzorci i manje serije za 24-48h,<br>ponuda u roku od par sati.</p>\n															<img width=\"28\" height=\"28\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/check.png\" alt=\"\" />																<h2 data-interaction-id=\"386245c3\">Kvalitet</h2>\n					<p data-interaction-id=\"2ea4366a\">Svaki komad prolazi kontrolu dimenzija<br>pre isporuke.</p>\n															<img width=\"28\" height=\"28\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/last.png\" alt=\"\" />																<h2 data-interaction-id=\"494d83eb\">Podrška</h2>\n					<p data-interaction-id=\"61cbbfa5\">Pomažemo pri pripremi CAD fajlova i<br>optimizaciji materijala.</p>\n					<img data-interaction-id=\"aa44314\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"https://www.instagram.com/mihalaser\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7