nzivnost za manje uređaje */\n@media (max-width: 480px) {\n  .tip-box {\n    padding: 20px;\n  }\n  .tip-text {\n    font-size: 13px;\n  }\n}\n</style>					\n    FORMA ZA UPIT\n      [text* tvoja-poruka placeholder \"Ime i prezime / naziv firme *\"]\n      [email* tvoj-email placeholder \"Email adresa *\"]\n      [tel* tvoj-telefon placeholder \"Broj telefona *\"]\n      [select tvoja-usluga \"Lasersko sečenje metala\" \"Lasersko graviranje\" \"Industrijsko obeležavanje\" \"CNC Obrada & Savijanje\"]\n    [textarea* detalji-upita rows:5 placeholder \"Detalji upita — materijal, debljina, dimenzije, količina... *\"]\n  [submit class:submit-btn \"POŠALJITE UPIT\"]\n<style>\n</style>					<img data-interaction-id=\"23dc2a3f\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"https://www.instagram.com/mihalaser\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 