INSERT INTO `wp_posts` VALUES (375,1,'2026-11-05 15:44:02','2026-11-05 15:44:02','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n									<p data-interaction-id=\"e852478\">// 02</p>\n					<h2 data-interaction-id=\"500e88b\">Lasersko Graviranje</h2>\n		<p>Precizno graviranje logotipa, natpisa, tekstura i serijskih oznaka na drvetu, pleksiglasu, akrilu, koži i metalu. Od reklamne galanterije do unikatnih personalizovanih poklona.</p>			\n  Fina mikronska linija\n  Trajan otisak\n  Reklamna galanterija\n  Unikatni pokloni\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n																			<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																										<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																<p data-interaction-id=\"75aa09d6\">// 03</p>\n					<h2 data-interaction-id=\"24b7dd35\">Industrijsko Obeležavanje</h2>\n		<p>Trajno obeležavanje mašinskih delova, alata, industrijskih tablica, QR kodova i serijskih brojeva na metalu. Obeležja otporna na habanje, hemikalije i visoke temperature.</p>			\n  Otporan na habanje\n  Barkod / QR kodovi\n  Alatni čelik i inoks\n  Brze serije\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n									<p data-interaction-id=\"4100fd6\">// 04</p>\n					<h2 data-interaction-id=\"3a2cce5\">CNC Obrada &amp; Savijanje</h2>\n		<p>Dodatna obrada, CNC glodanje, savijanje na apkan presi i izrada kompletnih sklopova po vašem nacrtu. Kompletna završna obrada do gotovog proizvoda.</p>			\n  Precizno savijanje lima\n  Glodanje metala\n  Izrada kućišta\n  Završna obrada\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n																			<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																<p data-interaction-id=\"6cf7be2b\">// MATERIJALI</p>\n					<h2 data-interaction-id=\"694b15da\">Maksimalne Debljine po Materijalu</h2>\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Crni čelik (S235/S355)\n    20 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Nerđajući čelik (Inox)\n    12 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Aluminijum\n    10 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Mesing\n    8 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Bakar\n    6 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Drvo / MDF (graviranje)\n    20 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Pleksiglas / Akril\n    15 mm\n<style>@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;700&display=swap\');\n.materials-table {\n  width: 100%;\n  max-width: 1232px;\n  background-color: #0b0f17;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: 8px;\n  padding: 10px 32px;\n  box-sizing: border-box;\n  font-family: \'Outfit\', sans-serif;\n}\n.material-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 18px 0;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n}\n.material-row:last-child {\n  border-bottom: none;\n}\n.material-left {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n.material-icon {\n  width: 18px;\n  height: 18px;\n  color: #00e5ff;\n  flex-shrink: 0;\n}\n.material-name {\n  font-size: 15px;\n  font-weight: 500;\n  color: #ffffff;\n}\n.material-value {\n  font-size: 15px;\n  font-weight: 700;\n  color: #ff3333;\n}\n.unit {\n  font-size: 13px;\n  font-weight: 400;\n  color: #ff3333;\n  margin-left: 2px;\n}\n/* Responzivnost za manje ekrane i mobilne */\n@media (max-width: 576px) {\n  .materials-table {\n    padding: 10px 16px;\n  }\n  .material-name {\n    font-size: 14px;\n  }\n  .material-value {\n    font-size: 14px;\n  }\n}</style>					<p data-interaction-id=\"7ff7a472\">// ČESTA PITANJA</p>\n					<h2 data-interaction-id=\"843f5db\">Odgovori na Najčešća Pitanja</h2>\n					Koje formate fajlova prihvatate?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Najbolje je poslati vektorske formate kao što su DXF, DWG, AI ili EPS. Ako imate samo skicu ili sliku sa dimenzijama, naš tim može pripremiti CAD model za vas.</p>\n					Koja je maksimalna debljina sečenja metala?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Naš fiber laser kapaciteta 6kW seče crni čelik do 20mm, nerđajući čelik (inoks) do 12mm i aluminijum do 10mm debljine.</p>\n					Koliko se čeka na izradu porudžbine?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Standardno vreme izrade za manje i srednje serije je 24 do 48 sati. Za veće industrijske serije rok se dogovara individualno.</p>\n					Da li vršite slanje gotovih komada na adresu?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Da, gotove proizvode šaljemo kurirskim službama širom Srbije, a za veće gabarite obezbeđujemo paletnu dostavu ili lično preuzimanje u radionici.</p>\n										<img data-interaction-id=\"7fae6052\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"https://www.instagram.com/mihalaser\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>					</a>\n							<h3>Navigacija</h3>							<ul>\n							<li>\n											<a href=\"/pocetna\">\n											Početna\n											</a>\n									</li>\n								<li>\n											<a href=\"/o-nama\">\n											O nama\n											</a>\n									</li>\n								<li>\n											<a href=\"/usluge\">\n											Usluge\n											</a>\n									</li>\n								<li>\n											<a href=\"/galerija\">\n											Galerija\n											</a>\n									</li>\n								<li>\n											<a href=\"/kontakt\">\n											Kontakt\n											</a>\n									</li>\n						</ul>\n							<h3>Kontakt</h3>							<ul>\n							<li>\n											<a href=\"#\">\n											+381 64 123 4567\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											info@mihalaser.rs\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Industrijska zona bb, 11000 Beograd, Srbija\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Pon - Pet: 08:00 - 17:00 | Sub: 08:00 - 14:00\n											</a>\n									</li>\n						</ul>\n							<p>© 2026 Miha Laser — Laserske usluge. Sva prava zadržana.</p>','Usluge','','inherit','closed','closed','','20-revision-v1','','','2026-11-05 15:44:02','2026-11-05 15:44:02','',20,'http://mihamiha.local/?p=375',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (376,1,'2026-11-05 15:45:23','2026-11-05 15:45:23','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n									<p data-interaction-id=\"e852478\">// 02</p>\n					<h2 data-interaction-id=\"500e88b\">Lasersko Graviranje</h2>\n		<p>Precizno graviranje logotipa, natpisa, tekstura i serijskih oznaka na drvetu, pleksiglasu, akrilu, koži i metalu. Od reklamne galanterije do unikatnih personalizovanih poklona.</p>			\n  Fina mikronska linija\n  Trajan otisak\n  Reklamna galanterija\n  Unikatni pokloni\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n																			<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																										<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																<p data-interaction-id=\"75aa09d6\">// 03</p>\n					<h2 data-interaction-id=\"24b7dd35\">Industrijsko Obeležavanje</h2>\n		<p>Trajno obeležavanje mašinskih delova, alata, industrijskih tablica, QR kodova i serijskih brojeva na metalu. Obeležja otporna na habanje, hemikalije i visoke temperature.</p>			\n  Otporan na habanje\n  Barkod / QR kodovi\n  Alatni čelik i inoks\n  Brze serije\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n									<p data-interaction-id=\"4100fd6\">// 04</p>\n					<h2 data-interaction-id=\"3a2cce5\">CNC Obrada &amp; Savijanje</h2>\n		<p>Dodatna obrada, CNC glodanje, savijanje na apkan presi i izrada kompletnih sklopova po vašem nacrtu. Kompletna završna obrada do gotovog proizvoda.</p>			\n  Precizno savijanje lima\n  Glodanje metala\n  Izrada kućišta\n  Završna obrada\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n																			<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																<p data-interaction-id=\"6cf7be2b\">// MATERIJALI</p>\n					<h2 data-interaction-id=\"694b15da\">Maksimalne Debljine po Materijalu</h2>\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Crni čelik (S235/S355)\n    20 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Nerđajući čelik (Inox)\n    12 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Aluminijum\n    10 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Mesing\n    8 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Bakar\n    6 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Drvo / MDF (graviranje)\n    20 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Pleksiglas / Akril\n    15 mm\n<style>@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;700&display=swap\');\n.materials-table {\n  width: 100%;\n  max-width: 1232px;\n  background-color: #0b0f17;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: 8px;\n  padding: 10px 32px;\n  box-sizing: border-box;\n  font-family: \'Outfit\', sans-serif;\n}\n.material-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 18px 0;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n}\n.material-row:last-child {\n  border-bottom: none;\n}\n.material-left {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n.material-icon {\n  width: 18px;\n  height: 18px;\n  color: #00e5ff;\n  flex-shrink: 0;\n}\n.material-name {\n  font-size: 15px;\n  font-weight: 500;\n  color: #ffffff;\n}\n.material-value {\n  font-size: 15px;\n  font-weight: 700;\n  color: #ff3333;\n}\n.unit {\n  font-size: 13px;\n  font-weight: 400;\n  color: #ff3333;\n  margin-left: 2px;\n}\n/* Responzivnost za manje ekrane i mobilne */\n@media (max-width: 576px) {\n  .materials-table {\n    padding: 10px 16px;\n  }\n  .material-name {\n    font-size: 14px;\n  }\n  .material-value {\n    font-size: 14px;\n  }\n}</style>					<p data-interaction-id=\"7ff7a472\">// ČESTA PITANJA</p>\n					<h2 data-interaction-id=\"843f5db\">Odgovori na Najčešća Pitanja</h2>\n					Koje formate fajlova prihvatate?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Najbolje je poslati vektorske formate kao što su DXF, DWG, AI ili EPS. Ako imate samo skicu ili sliku sa dimenzijama, naš tim može pripremiti CAD model za vas.</p>\n					Koja je maksimalna debljina sečenja metala?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Naš fiber laser kapaciteta 6kW seče crni čelik do 20mm, nerđajući čelik (inoks) do 12mm i aluminijum do 10mm debljine.</p>\n					Koliko se čeka na izradu porudžbine?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Standardno vreme izrade za manje i srednje serije je 24 do 48 sati. Za veće industrijske serije rok se dogovara individualno.</p>\n					Da li vršite slanje gotovih komada na adresu?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Da, gotove proizvode šaljemo kurirskim službama širom Srbije, a za veće gabarite obezbeđujemo paletnu dostavu ili lično preuzimanje u radionici.</p>\n										<img data-interaction-id=\"7fae6052\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"https://www.instagram.com/mihalaser\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>					</a>\n							<h3>Navigacija</h3>							<ul>\n							<li>\n											<a href=\"/pocetna\">\n											Početna\n											</a>\n									</li>\n								<li>\n											<a href=\"/o-nama\">\n											O nama\n											</a>\n									</li>\n								<li>\n											<a href=\"/usluge\">\n											Usluge\n											</a>\n									</li>\n								<li>\n											<a href=\"/galerija\">\n											Galerija\n											</a>\n									</li>\n								<li>\n											<a href=\"/kontakt\">\n											Kontakt\n											</a>\n									</li>\n						</ul>\n							<h3>Kontakt</h3>							<ul>\n							<li>\n											<a href=\"#\">\n											+381 64 123 4567\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											info@mihalaser.rs\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Industrijska zona bb, 11000 Beograd, Srbija\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Pon - Pet: 08:00 - 17:00 | Sub: 08:00 - 14:00\n											</a>\n									</li>\n						</ul>\n							<p>© 2026 Miha Laser — Laserske usluge. Sva prava zadržana.</p>','Usluge','','inherit','closed','closed','','20-revision-v1','','','2026-11-05 15:45:23','2026-11-05 15:45:23','',20,'http://mihamiha.local/?p=376',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (377,1,'2026-11-05 15:45:24','2026-11-05 15:45:24','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n									<p data-interaction-id=\"e852478\">// 02</p>\n					<h2 data-interaction-id=\"500e88b\">Lasersko Graviranje</h2>\n		<p>Precizno graviranje logotipa, natpisa, tekstura i serijskih oznaka na drvetu, pleksiglasu, akrilu, koži i metalu. Od reklamne galanterije do unikatnih personalizovanih poklona.</p>			\n  Fina mikronska linija\n  Trajan otisak\n  Reklamna galanterija\n  Unikatni pokloni\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n																			<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																										<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																<p data-interaction-id=\"75aa09d6\">// 03</p>\n					<h2 data-interaction-id=\"24b7dd35\">Industrijsko Obeležavanje</h2>\n		<p>Trajno obeležavanje mašinskih delova, alata, industrijskih tablica, QR kodova i serijskih brojeva na metalu. Obeležja otporna na habanje, hemikalije i visoke temperature.</p>			\n  Otporan na habanje\n  Barkod / QR kodovi\n  Alatni čelik i inoks\n  Brze serije\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n									<p data-interaction-id=\"4100fd6\">// 04</p>\n					<h2 data-interaction-id=\"3a2cce5\">CNC Obrada &amp; Savijanje</h2>\n		<p>Dodatna obrada, CNC glodanje, savijanje na apkan presi i izrada kompletnih sklopova po vašem nacrtu. Kompletna završna obrada do gotovog proizvoda.</p>			\n  Precizno savijanje lima\n  Glodanje metala\n  Izrada kućišta\n  Završna obrada\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n																			<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																<p data-interaction-id=\"6cf7be2b\">// MATERIJALI</p>\n					<h2 data-interaction-id=\"694b15da\">Maksimalne Debljine po Materijalu</h2>\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Crni čelik (S235/S355)\n    20 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Nerđajući čelik (Inox)\n    12 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Aluminijum\n    10 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Mesing\n    8 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Bakar\n    6 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Drvo / MDF (graviranje)\n    20 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Pleksiglas / Akril\n    15 mm\n<style>@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;700&display=swap\');\n.materials-table {\n  width: 100%;\n  max-width: 1232px;\n  background-color: #0b0f17;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: 8px;\n  padding: 10px 32px;\n  box-sizing: border-box;\n  font-family: \'Outfit\', sans-serif;\n}\n.material-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 18px 0;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n}\n.material-row:last-child {\n  border-bottom: none;\n}\n.material-left {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n.material-icon {\n  width: 18px;\n  height: 18px;\n  color: #00e5ff;\n  flex-shrink: 0;\n}\n.material-name {\n  font-size: 15px;\n  font-weight: 500;\n  color: #ffffff;\n}\n.material-value {\n  font-size: 15px;\n  font-weight: 700;\n  color: #ff3333;\n}\n.unit {\n  font-size: 13px;\n  font-weight: 400;\n  color: #ff3333;\n  margin-left: 2px;\n}\n/* Responzivnost za manje ekrane i mobilne */\n@media (max-width: 576px) {\n  .materials-table {\n    padding: 10px 16px;\n  }\n  .material-name {\n    font-size: 14px;\n  }\n  .material-value {\n    font-size: 14px;\n  }\n}</style>					<p data-interaction-id=\"7ff7a472\">// ČESTA PITANJA</p>\n					<h2 data-interaction-id=\"843f5db\">Odgovori na Najčešća Pitanja</h2>\n					Koje formate fajlova prihvatate?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Najbolje je poslati vektorske formate kao što su DXF, DWG, AI ili EPS. Ako imate samo skicu ili sliku sa dimenzijama, naš tim može pripremiti CAD model za vas.</p>\n					Koja je maksimalna debljina sečenja metala?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Naš fiber laser kapaciteta 6kW seče crni čelik do 20mm, nerđajući čelik (inoks) do 12mm i aluminijum do 10mm debljine.</p>\n					Koliko se čeka na izradu porudžbine?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Standardno vreme izrade za manje i srednje serije je 24 do 48 sati. Za veće industrijske serije rok se dogovara individualno.</p>\n					Da li vršite slanje gotovih komada na adresu?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Da, gotove proizvode šaljemo kurirskim službama širom Srbije, a za veće gabarite obezbeđujemo paletnu dostavu ili lično preuzimanje u radionici.</p>\n										<img data-interaction-id=\"7fae6052\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"https://www.instagram.com/mihalaser\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>					</a>\n							<h3>Navigacija</h3>							<ul>\n							<li>\n											<a href=\"/pocetna\">\n											Početna\n											</a>\n									</li>\n								<li>\n											<a href=\"/o-nama\">\n											O nama\n											</a>\n									</li>\n								<li>\n											<a href=\"/usluge\">\n											Usluge\n											</a>\n									</li>\n								<li>\n											<a href=\"/galerija\">\n											Galerija\n											</a>\n									</li>\n								<li>\n											<a href=\"/kontakt\">\n											Kontakt\n											</a>\n									</li>\n						</ul>\n							<h3>Kontakt</h3>							<ul>\n							<li>\n											<a href=\"#\">\n											+381 64 123 4567\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											info@mihalaser.rs\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Industrijska zona bb, 11000 Beograd, Srbija\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Pon - Pet: 08:00 - 17:00 | Sub: 08:00 - 14:00\n											</a>\n									</li>\n						</ul>\n							<p>© 2026 Miha Laser — Laserske usluge. Sva prava zadržana.</p>','Usluge','','inherit','closed','closed','','20-revision-v1','','','2026-11-05 15:45:24','2026-11-05 15:45:24','',20,'http://mihamiha.local/?p=377',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (378,1,'2026-11-05 15:45:24','2026-11-05 15:45:24','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n																			<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																<p data-interaction-id=\"75aa09d6\">// 01</p>\n					<h2 data-interaction-id=\"24b7dd35\">Lasersko Sečenje Metala</h2>\n		<p>Visokoefikasno fiber sečenje crnog lima, inoksa, aluminijuma i mesinga čistih ivica bez potrebe za dodatnom obradom. Idealno za serijsku proizvodnju, dekorativne panele, ograde i mašinske delove.</p>			\n  Čelik do 20mm\n  Inoks do 12mm\n  Aluminijum do 10mm\n  Sto 3000x1500mm\nZatraži ponudu\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n									<p data-interaction-id=\"e852478\">// 02</p>\n					<h2 data-interaction-id=\"500e88b\">Lasersko Graviranje</h2>\n		<p>Precizno graviranje logotipa, natpisa, tekstura i serijskih oznaka na drvetu, pleksiglasu, akrilu, koži i metalu. Od reklamne galanterije do unikatnih personalizovanih poklona.</p>			\n  Fina mikronska linija\n  Trajan otisak\n  Reklamna galanterija\n  Unikatni pokloni\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n																			<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																										<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																<p data-interaction-id=\"7dbfe20\">// 03</p>\n					<h2 data-interaction-id=\"4d2e910\">Industrijsko Obeležavanje</h2>\n		<p>Trajno obeležavanje mašinskih delova, alata, industrijskih tablica, QR kodova i serijskih brojeva na metalu. Obeležja otporna na habanje, hemikalije i visoke temperature.</p>			\n  Otporan na habanje\n  Barkod / QR kodovi\n  Alatni čelik i inoks\n  Brze serije\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n									<p data-interaction-id=\"4100fd6\">// 04</p>\n					<h2 data-interaction-id=\"3a2cce5\">CNC Obrada &amp; Savijanje</h2>\n		<p>Dodatna obrada, CNC glodanje, savijanje na apkan presi i izrada kompletnih sklopova po vašem nacrtu. Kompletna završna obrada do gotovog proizvoda.</p>			\n  Precizno savijanje lima\n  Glodanje metala\n  Izrada kućišta\n  Završna obrada\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n																			<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																<p data-interaction-id=\"6cf7be2b\">// MATERIJALI</p>\n					<h2 data-interaction-id=\"694b15da\">Maksimalne Debljine po Materijalu</h2>\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Crni čelik (S235/S355)\n    20 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Nerđajući čelik (Inox)\n    12 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Aluminijum\n    10 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Mesing\n    8 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Bakar\n    6 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Drvo / MDF (graviranje)\n    20 mm\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>\n      Pleksiglas / Akril\n    15 mm\n<style>@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;700&display=swap\');\n.materials-table {\n  width: 100%;\n  max-width: 1232px;\n  background-color: #0b0f17;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: 8px;\n  padding: 10px 32px;\n  box-sizing: border-box;\n  font-family: \'Outfit\', sans-serif;\n}\n.material-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 18px 0;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n}\n.material-row:last-child {\n  border-bottom: none;\n}\n.material-left {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n.material-icon {\n  width: 18px;\n  height: 18px;\n  color: #00e5ff;\n  flex-shrink: 0;\n}\n.material-name {\n  font-size: 15px;\n  font-weight: 500;\n  color: #ffffff;\n}\n.material-value {\n  font-size: 15px;\n  font-weight: 700;\n  color: #ff3333;\n}\n.unit {\n  font-size: 13px;\n  font-weight: 400;\n  color: #ff3333;\n  margin-left: 2px;\n}\n/* Responzivnost za manje ekrane i mobilne */\n@media (max-width: 576px) {\n  .materials-table {\n    padding: 10px 16px;\n  }\n  .material-name {\n    font-size: 14px;\n  }\n  .material-value {\n    font-size: 14px;\n  }\n}</style>					<p data-interaction-id=\"7ff7a472\">// ČESTA PITANJA</p>\n					<h2 data-interaction-id=\"843f5db\">Odgovori na Najčešća Pitanja</h2>\n					Koje formate fajlova prihvatate?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Najbolje je poslati vektorske formate kao što su DXF, DWG, AI ili EPS. Ako imate samo skicu ili sliku sa dimenzijama, naš tim može pripremiti CAD model za vas.</p>\n					Koja je maksimalna debljina sečenja metala?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Naš fiber laser kapaciteta 6kW seče crni čelik do 20mm, nerđajući čelik (inoks) do 12mm i aluminijum do 10mm debljine.</p>\n					Koliko se čeka na izradu porudžbine?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Standardno vreme izrade za manje i srednje serije je 24 do 48 sati. Za veće industrijske serije rok se dogovara individualno.</p>\n					Da li vršite slanje gotovih komada na adresu?<svg aria-hidden=\"true\" viewBox=\"0 0 256 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z\"></path></svg><p>Da, gotove proizvode šaljemo kurirskim službama širom Srbije, a za veće gabarite obezbeđujemo paletnu dostavu ili lično preuzimanje u radionici.</p>\n										<img data-interaction-id=\"7fae6052\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"https://www.instagram.com/mihalaser\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>					</a>\n							<h3>Navigacija</h3>							<ul>\n							<li>\n											<a href=\"/pocetna\">\n											Početna\n											</a>\n									</li>\n								<li>\n											<a href=\"/o-nama\">\n											O nama\n											</a>\n									</li>\n								<li>\n											<a href=\"/usluge\">\n											Usluge\n											</a>\n									</li>\n								<li>\n											<a href=\"/galerija\">\n											Galerija\n											</a>\n									</li>\n								<li>\n											<a href=\"/kontakt\">\n											Kontakt\n											</a>\n									</li>\n						</ul>\n							<h3>Kontakt</h3>							<ul>\n							<li>\n											<a href=\"#\">\n											+381 64 123 4567\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											info@mihalaser.rs\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Industrijska zona bb, 11000 Beograd, Srbija\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											Pon - Pet: 08:00 - 17:00 | Sub: 08:00 - 14:00\n											</a>\n									</li>\n						</ul>\n							<p>© 2026 Miha Laser — Laserske usluge. Sva prava zadržana.</p>','Usluge','','inherit','closed','closed','','20-revision-v1','','','2026-11-05 15:45:24','2026-11-05 15:45:24','',20,'http://mihamiha.local/?p=378',0,'revision','',0);
