INSERT INTO `wp_posts` VALUES (383,1,'2026-11-05 16:20:03','2026-11-05 16:20:03','<a href=\"http://mihamiha.local/\">\n							<img width=\"130\" height=\"36\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" alt=\"\" />								</a>\n																<style>\n                        @media screen and (max-width: 1024px) {\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-horizontal,\n                                .eael-simple-menu-vertical {\n                                    display: none;\n                                }\n                            }\n                            .eael-hamburger--tablet {\n                                .eael-simple-menu-container .eael-simple-menu-toggle {\n                                    display: block;\n                                }\n                            }\n                        }\n                    </style><style>\n                        @media screen and (min-width: 1025px) {\n                        /* Left aligned horizontal menus lay out with `float: left` on the\n                           items, so their list stays `block` - forcing flex here would\n                           take the items out of flow and break the row. Only centre and\n                           right aligned horizontal menus are inline-flex. */\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-horizontal,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading > ul.eael-simple-menu-vertical {\n                            display: block;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center {\n                            text-align: center;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-1afaf457 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a href=\"#\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n																			<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																<p data-interaction-id=\"75aa09d6\">// 01</p>\n					<h2 data-interaction-id=\"24b7dd35\">Lasersko Sečenje Metala</h2>\n		<p>Visokoefikasno fiber sečenje crnog lima, inoksa, aluminijuma i mesinga čistih ivica bez potrebe za dodatnom obradom. Idealno za serijsku proizvodnju, dekorativne panele, ograde i mašinske delove.</p>			\n  Čelik do 20mm\n  Inoks do 12mm\n  Aluminijum do 10mm\n  Sto 3000x1500mm\nZatraži ponudu\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n									<p data-interaction-id=\"e852478\">// 02</p>\n					<h2 data-interaction-id=\"500e88b\">Lasersko Graviranje</h2>\n		<p>Precizno graviranje logotipa, natpisa, tekstura i serijskih oznaka na drvetu, pleksiglasu, akrilu, koži i metalu. Od reklamne galanterije do unikatnih personalizovanih poklona.</p>			\n  Fina mikronska linija\n  Trajan otisak\n  Reklamna galanterija\n  Unikatni pokloni\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\n  font-family: \'Outfit\', sans-serif;\n  box-sizing: border-box;\n  margin-bottom: 24px;\n}\n.feature-card {\n  background-color: #121824; /* Unutrašnja tamnija nijansa kao na slici */\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 0px;\n  padding: 10px 14px; /* Znatno manji padding da ne budu debele */\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 400;\n  text-align: center;\n  white-space: nowrap;\n  box-sizing: border-box;\n  flex: 1 1 auto;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n.feature-card:hover {\n  border-color: #00e5ff;\n  color: #ffffff;\n}\n/* Responzivnost za manji ekran */\n@media (max-width: 640px) {\n  .cards-grid {\n    gap: 6px;\n  }\n  .feature-card {\n    padding: 8px 10px;\n    font-size: 12px;\n    white-space: normal;\n  }\n}\n</style>										<a href=\"/kontakt\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M190.5 66.9l22.2-22.2c9.4-9.4 24.6-9.4 33.9 0L441 239c9.4 9.4 9.4 24.6 0 33.9L246.6 467.3c-9.4 9.4-24.6 9.4-33.9 0l-22.2-22.2c-9.5-9.5-9.3-25 .4-34.3L311.4 296H24c-13.3 0-24-10.7-24-24v-32c0-13.3 10.7-24 24-24h287.4L190.9 101.2c-9.8-9.3-10-24.8-.4-34.3z\"></path></svg>			\n									ZATRAŽI PONUDU\n					</a>\n																			<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																										<img width=\"584\" height=\"380\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png\" alt=\"\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Container.png 584w, http://mihamiha.local/wp-content/uploads/2026/11/Container-300x195.png 300w\" sizes=\"(max-width: 584px) 100vw, 584px\" />																<p data-interaction-id=\"7dbfe20\">// 03</p>\n					<h2 data-interaction-id=\"4d2e910\">Industrijsko Obeležavanje</h2>\n		<p>Trajno obeležavanje mašinskih delova, alata, industrijskih tablica, QR kodova i serijskih brojeva na metalu. Obeležja otporna na habanje, hemikalije i visoke temperature.</p>			\n  Otporan na habanje\n  Barkod / QR kodovi\n  Alatni čelik i inoks\n  Brze serije\n<style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500&display=swap\');\n.cards-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  width: 100%;\n  max-width: 580px;\