b3 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right {\n                            text-align: right;\n                        }\n                        .elementor-element-36a79bb3 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-center > ul.eael-simple-menu-horizontal,\n                        .elementor-element-36a79bb3 .eael-simple-menu-container.eael-simple-menu--loading.eael-simple-menu-align-right > ul.eael-simple-menu-horizontal {\n                            display: -webkit-inline-box;\n                            display: -ms-inline-flexbox;\n                            display: inline-flex;\n                        }\n                        .elementor-element-36a79bb3 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle,\n                        .elementor-element-36a79bb3 .eael-simple-menu-container.eael-simple-menu--loading .eael-simple-menu-toggle-text {\n                            display: none;\n                        }\n                        }\n                    </style>            \n                <ul id=\"menu-main\"><li id=\"menu-item-30\"><a href=\"http://mihamiha.local/pocetna/\">Pocetna</a></li>\n<li id=\"menu-item-29\"><a href=\"http://mihamiha.local/o-nama/\">O nama</a></li>\n<li id=\"menu-item-28\"><a href=\"http://mihamiha.local/usluge/\">Usluge</a></li>\n<li id=\"menu-item-27\"><a href=\"http://mihamiha.local/galerija/\">Galerija</a></li>\n<li id=\"menu-item-26\"><a href=\"http://mihamiha.local/kontakt/\">Kontakt</a></li>\n</ul>                <button>\n                    Hamburger Toggle Menu\n                    <svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M16 132h416c8.837 0 16-7.163 16-16V76c0-8.837-7.163-16-16-16H16C7.163 60 0 67.163 0 76v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16zm0 160h416c8.837 0 16-7.163 16-16v-40c0-8.837-7.163-16-16-16H16c-8.837 0-16 7.163-16 16v40c0 8.837 7.163 16 16 16z\"></path></svg>                </button>\n            										<a role=\"button\">\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>			\n									+381 64 123 4567\n					</a>\n						<p>// GALERIJA</p>			<h2 data-interaction-id=\"330031cc\">Primeri Izrađenih Pozicija i Dekorativnih Panela</h2>\n					<p data-interaction-id=\"5e00ddd5\">Pogledajte deo onoga što izlazi iz naše radionice — od industrijskih delova do dekorativnih rešenja.</p>\n					<style id=\"eael-fg-inline-css-bade274\">@media only screen and (max-width: 2399px) {\n					.elementor-element.elementor-element-bade274 .eael-filterable-gallery-item-wrap {\n					        width: 33.333333333333%;\n					    }\n					}@media only screen and (max-width: 1024px) {\n					.elementor-element.elementor-element-bade274  .eael-filterable-gallery-item-wrap {\n					        width: 50%;\n					    }\n					}@media only screen and (max-width: 767px) {\n					.elementor-element.elementor-element-bade274  .eael-filterable-gallery-item-wrap {\n					        width: 100%;\n					    }\n					}</style>        \n                <ul><li data-load-more-status=\"0\" data-first-init=\"1\" data-filter=\"*\">Sve</li><li  data-load-more-status=\"0\" data-first-init=\"0\"\n                        data-filter=\".eael-cf-metalna-arhitektura\">Metalna arhitektura</li><li  data-load-more-status=\"0\" data-first-init=\"0\"\n                        data-filter=\".eael-cf-industrijski-delovi\">Industrijski delovi</li><li  data-load-more-status=\"0\" data-first-init=\"0\"\n                        data-filter=\".eael-cf-graviranje\">Graviranje</li><li  data-load-more-status=\"0\" data-first-init=\"0\"\n                        data-filter=\".eael-cf-cnc-obrada\">CNC obrada</li></ul>\n				<img width=\"300\" height=\"195\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Lasersko-Graviranje-300x195.png\" alt=\"\" decoding=\"async\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Lasersko-Graviranje-300x195.png 300w, http://mihamiha.local/wp-content/uploads/2026/11/Lasersko-Graviranje.png 584w\" sizes=\"(max-width: 300px) 100vw, 300px\" /><a area-hidden=\"true\" aria-label=\"eael-magnific-link\" href=\"http://mihamiha.local/wp-content/uploads/2026/11/Lasersko-Graviranje.png\" data-elementor-open-lightbox=\"yes\" title=\"\"><h2>Dekorativni laserski rezani panel</h2>Metalna arhitektura\n</a>\n				<img width=\"300\" height=\"195\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Lasersko-secenje-inoks-masinskog-prstena-300x195.png\" alt=\"\" decoding=\"async\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Lasersko-secenje-inoks-masinskog-prstena-300x195.png 300w, http://mihamiha.local/wp-content/uploads/2026/11/Lasersko-secenje-inoks-masinskog-prstena.png 393w\" sizes=\"(max-width: 300px) 100vw, 300px\" /><a area-hidden=\"true\" aria-label=\"eael-magnific-link\" href=\"http://mihamiha.local/wp-content/uploads/2026/11/Lasersko-secenje-inoks-masinskog-prstena.png\" data-elementor-open-lightbox=\"yes\" title=\"\"><h2>Lasersko sečenje inoks mašinskog prstena</h2></a>\n				<img width=\"300\" height=\"195\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Fiber-secenje-lima-u-pokretu-300x195.png\" alt=\"\" decoding=\"async\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Fiber-secenje-lima-u-pokretu-300x195.png 300w, http://mihamiha.local/wp-content/uploads/2026/11/Fiber-secenje-lima-u-pokretu.png 393w\" sizes=\"(max-width: 300px) 100vw, 300px\" /><a area-hidden=\"true\" aria-label=\"eael-magnific-link\" href=\"http://mihamiha.local/wp-content/uploads/2026/11/Fiber-secenje-lima-u-pokretu.png\" data-elementor-open-lightbox=\"yes\" title=\"\"><h2>Fiber sečenje lima u pokretu</h2></a>\n				<img width=\"300\" height=\"195\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Dekorativni-laserski-rezani-panel-300x195.png\" alt=\"\" decoding=\"async\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Dekorativni-laserski-rezani-panel-300x195.png 300w, http://mihamiha.local/wp-content/uploads/2026/11/Dekorativni-laserski-rezani-panel.png 393w\" sizes=\"(max-width: 300px) 100vw, 300px\" /><a area-hidden=\"true\" aria-label=\"eael-magnific-link\" href=\"http://mihamiha.local/wp-content/uploads/2026/11/Dekorativni-laserski-rezani-panel.png\" data-elementor-open-lightbox=\"yes\" title=\"\"><h2>Dekorativni panel</h2></a>\n				<img width=\"300\" height=\"195\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Gravirani-drveni-panel-sa-logotipom-300x195.png\" alt=\"\" decoding=\"async\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Gravirani-drveni-panel-sa-logotipom-300x195.png 300w, http://mihamiha.local/wp-content/uploads/2026/11/Gravirani-drveni-panel-sa-logotipom.png 393w\" sizes=\"(max-width: 300px) 100vw, 300px\" /><a area-hidden=\"true\" aria-label=\"eael-magnific-link\" href=\"http://mihamiha.local/wp-content/uploads/2026/11/Gravirani-drveni-panel-sa-logotipom.png\" data-elementor-open-lightbox=\"yes\" title=\"\"><h2>Gravirani drveni panel sa logotipom</h2></a>\n				<img width=\"300\" height=\"195\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/Geometrijska-ograda-od-secenog-lima-300x195.png\" alt=\"\" decoding=\"async\" srcset=\"http://mihamiha.local/wp-content/uploads/2026/11/Geometrijska-ograda-od-secenog-lima-300x195.png 300w, http://mihamiha.local/wp-content/uploads/2026/11/Geometrijska-ograda-od-secenog-lima.png 393w\" sizes=\"(max-width: 300px) 100vw, 300px\" /><a area-hidden=\"true\" aria-label=\"eael-magnific-link\" href=\"http://mihamiha.local/wp-content/uploads/2026/11/Geometrijska-ograda-od-secenog-lima.png\" data-elementor-open-lightbox=\"yes\" title=\"\"><h2>Geometrijska ograda od sečenog lima</h2></a>        \n        					<img data-interaction-id=\"2308119d\" id=\"11\" src=\"http://mihamiha.local/wp-content/uploads/2026/11/mihalogo.png\" width=\"130\" height=\"36\" srcset=\"\" alt=\"\"/>					<p>Mikronska preciznost laserskog sečenja i graviranja.\nFiber i CO2 laserska obrada metala i nemetala.</p>							\n					<a href=\"#\">\n						Facebook-f\n						<svg aria-hidden=\"true\" viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M279.14 288l14.22-92.66h-88.91v-60.13c0-25.35 12.42-50.06 52.24-50.06h40.42V6.26S260.43 0 225.36 0c-73.22 0-121.08 44.38-121.08 124.72v70.62H22.89V288h81.39v224h100.17V288z\"></path></svg>					</a>\n					<a href=\"https://www.instagram.com/mihalaser\">\n						Instagram\n						<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>					</a>\n							<h3>Navigacija</h3>							<ul>\n							<li>\n											<a href=\"/pocetna\">